/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Occupazione greca di Lemno", "9555af1d"], "d": ["Nella Prima guerra balcanica la flotta greca occupò Lemno; il porto di Mudros dell'isola divenne base per il blocco dei Dardanelli. L'isola fu lasciata alla Grecia a Losanna (24 luglio 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Occupazione greca di Taso", "6c03c7f0"], "d": ["Nella Prima guerra balcanica la Grecia occupò Taso e Samotracia.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Occupazione greca di Samotracia", "911e82a3"], "d": ["Nella Prima guerra balcanica la Grecia occupò Samotracia.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Occupazione greca di Mitilene (Lesbo)", "6b2b07ba"], "d": ["La flotta greca sbarcò a Mitilene; l'isola alla fine della Prima guerra balcanica fu presa dall'esercito e dalla flotta greci. La Conferenza di Londra (maggio 1913) confermò la situazione.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Sbarco greco a Chio", "901c6539"], "d": ["A Chio, bombardata il 7 aprile 1912 nella Prima guerra balcanica, i Greci effettuarono lo sbarco; la guarnigione ottomana si arrese il 3 gennaio 1913. L'isola fu lasciata alla Grecia con il Trattato di Losanna (24 luglio 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Uccisione per attentato a Istanbul del gran visir Mahmud Şevket Pascià", "68e60e63"], "d": ["Mahmud Şevket Pascià, nominato gran visir dopo l'irruzione alla Sublime Porta, fu ucciso dai colpi sparati contro la sua carrozza presso Çarşıkapı mentre si recava al Ministero della Guerra. Il Comitato Unione e Progresso, addossando l'attentato all'opposizione, avviò una vasta ondata di arresti ed esecuzioni e il Partito della Libertà e dell'Intesa fu di fatto liquidato. Con questo fatto fu stabilita in modo definitivo la dittatura a partito unico degli unionisti, fondata sul triumvirato Enver-Talat-Cemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Inizio della Seconda guerra balcanica: lite degli alleati per la spartizione", "48d088a2"], "d": ["Gli alleati balcanici, che non riuscivano a spartirsi i territori tolti agli Ottomani con il Trattato di Londra, si scontrarono tra loro; con l'attacco della Bulgaria alle posizioni serbe e greche iniziò la seconda guerra. Quando anche Romania e Montenegro entrarono in campo contro la Bulgaria l'esercito bulgaro crollò. L'Impero ottomano, approfittando dell'occasione, superò la linea Midye-Enez tracciata dal Trattato di Londra e riprese la Tracia orientale con Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Trattato di Istanbul: pace con la Bulgaria e registrazione di Edirne", "c8c18b2d"], "d": ["Il trattato firmato tra l'Impero ottomano e la Bulgaria dopo la Seconda guerra balcanica, riconoscendo il fiume Maritza (Meriç) come confine, sancì giuridicamente che Edirne, Kırklareli, Dimetoka e la Tracia orientale restassero agli Ottomani. Dedeağaç fu lasciata alla Bulgaria (Kavala invece era passata alla Grecia nel luglio 1913 dopo l'occupazione bulgara dell'autunno 1912 ed era stata registrata come greca con il Trattato di Bucarest del 10 agosto 1913), furono regolati uno scambio reciproco di popolazione tra i due paesi e i diritti dei musulmani in Bulgaria. Questo testo è la garanzia dell'unico lembo di territorio che fu possibile riprendere dal disastro balcanico. Aynı tarihte katılan öteki yerler: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Ripresa di Bozcaada e Imbro — Trattato di Atene", "ec084d09"], "d": ["Bozcaada e Imbro, che tengono l'imboccatura dello Stretto, tra le isole dell'Egeo settentrionale occupate dalla Grecia nella Guerra balcanica, furono considerate indispensabili per la difesa di Çanakkale nei negoziati del Trattato di Atene e furono restituite agli Ottomani. Le altre isole restarono alla Grecia. Queste due isole furono gli ultimi territori che l'Impero tenne nell'Egeo e furono lasciate alla Turchia anche a Losanna.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Trattato di Atene: pace con la Grecia e cessione di Salonicco e Ioannina", "8e94def7"], "d": ["Il trattato firmato tra l'Impero ottomano e la Grecia riconobbe ufficialmente il passaggio alla Grecia di Salonicco, Ioannina e Macedonia meridionale, perdute nella Guerra balcanica, e fu abbandonato ogni diritto ottomano su Creta. Furono regolati in dettaglio i diritti di religione e proprietà dei musulmani rimasti in Grecia, lo statuto dei vakıf e la nomina dei müftü. Lo statuto delle isole dell'Egeo fu invece lasciato irrisolto e rimase una fonte di tensione continua tra i due Stati.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Firma a Istanbul del trattato segreto d'alleanza ottomano-tedesco", "0472efb3"], "d": ["Non appena scoppiò la guerra in Europa, nel palazzo del gran visir Said Halim Pascià fu firmato un trattato segreto d'alleanza tra l'Impero ottomano e la Germania; il testo prevedeva che, nel caso la Russia fosse entrata in guerra contro la Germania, gli Ottomani si schierassero con la Germania. Il trattato fu nascosto persino al gabinetto ed era noto solo a quattro persone. Tre mesi dopo, con l'incursione nel Mar Nero, l'Impero ottomano sarebbe stato di fatto trascinato in guerra e il destino dell'Impero fu legato con questo documento.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Abolizione unilaterale delle capitolazioni", "ec773d18"], "d": ["Il governo ottomano, in un momento in cui l'Europa era impegnata nella guerra, dichiarò di abolire unilateralmente dal 1° ottobre 1914 le capitolazioni, che riconoscevano agli stranieri privilegi giudiziari, finanziari e doganali. La fine di questo ordinamento di privilegi quadricentenario fu accolta nel paese con grande entusiasmo d'indipendenza e a Istanbul si tennero celebrazioni. Tutti gli Stati, compresa l'alleata Germania, protestarono contro la decisione; le capitolazioni sarebbero entrate definitivamente nella storia solo nel 1923 a Losanna.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Incursione nel Mar Nero: bombardamento dei porti russi da parte della flotta ottomana", "8ad4ef61"], "d": ["Il Goeben e il Breslau (Yavuz e Midilli), fuggiti dalla Germania e uniti alla flotta ottomana come se fossero stati 'acquistati', al comando dell'ammiraglio Souchon si spinsero nel Mar Nero, bombardarono i porti russi e affondarono navi. Questo ordine, dato da Enver Pascià all'insaputa del gabinetto, pose fine di fatto alla neutralità. Entro una settimana Russia, Inghilterra e Francia dichiararono guerra e l'Impero ottomano entrò nella Prima guerra mondiale in modo irreversibile.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Presa di Fao da parte delle forze anglo-indiane — apertura del fronte iracheno", "08663813"], "d": ["La mattina successiva al giorno in cui gli Stati dell'Intesa dichiararono guerra all'Impero ottomano, la brigata anglo-indiana in attesa a Bahrein sbarcò a Fao, alla foce dello Shatt al-Arab. Il piccolo reparto ottomano nella fortezza in rovina di Fao si ritirò sotto il fuoco delle navi da guerra e la stazione della linea telegrafica dell'India passò in mano agli Inglesi. Il fronte iracheno fu così aperto.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Proclamazione del Cihâd-ı Ekber: lettura della fatwa del jihad nella moschea di Fatih", "2a6174e8"], "d": ["Le cinque fatwa emesse dallo şeyhülislam Ürgüplü Hayri Efendi furono lette nella moschea di Fatih a nome del sultano-califfo e tutti i musulmani furono chiamati al jihad contro gli Stati dell'Intesa. Questa mossa, su cui la Germania riponeva grandi speranze, mirava a sollevare i musulmani delle colonie inglesi e francesi. La sollevazione generale attesa non avvenne; al contrario, la rivolta dell'emiro della Mecca Sharif Husayn con il sostegno inglese, due anni dopo, mostrò amaramente i limiti dell'influenza politica del califfato.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Resa di Qurna agli Inglesi", "621d36b0"], "d": ["Le forze del governatore di Bassora Subhi Bey, ritiratesi dopo la caduta di Bassora a Qurna, dove si uniscono Tigri ed Eufrate, dopo gli scontri del 4-8 dicembre si arresero la mattina del 9 dicembre 1914.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Protettorato britannico sull'Egitto e proclamazione del sultanato", "55d4e520"], "d": ["Con l'entrata in guerra dell'Impero ottomano l'Inghilterra dichiarò di porre ufficialmente sotto la propria protezione l'Egitto, che occupava di fatto dal 1882; il khedivé Abbas Hilmi Pascià, rimasto fedele agli Ottomani, fu destituito e al suo posto fu messo Hüseyin Kâmil con il titolo di 'sultano'. Così la sovranità giuridica ottomana, in vigore dal 1517, fu fatta cessare unilateralmente. La Sublime Porta non riconobbe la decisione e due mesi dopo tentò di riprendere l'Egitto con l'Operazione del Canale.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Operazione di Sarıkamış: disastro sul fronte del Caucaso", "5cbde7f0"], "d": ["Enver Pascià, con lo scopo di riprendere Kars-Ardahan-Batum, perduti nel 1878, e di sollevare i Turchi del Caucaso, spinse in inverno la III Armata, attraverso i monti Allahuekber, in una manovra per accerchiare le forze russe. Per l'equipaggiamento invernale insufficiente, i rifornimenti esauriti e le tormente fino a trenta gradi sotto zero, l'armata si sciolse prima ancora di entrare in battaglia; decine di migliaia di soldati morirono assiderati. L'operazione fu uno dei più gravi disastri ottomani nella guerra e lasciò il fronte orientale indifeso per due anni.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Prima Operazione del Canale: attacco a Suez attraverso il deserto del Sinai", "02dd72f5"], "d": ["Il comandante della IV Armata Cemal Pascià, con lo scopo di liberare l'Egitto dall'occupazione britannica e di chiudere il Canale di Suez alla navigazione, organizzò un attacco attraverso il deserto del Sinai. Anche se le unità ottomane raggiunsero la riva orientale del canale e alcune riuscirono ad attraversarlo, si ritirarono per la superiorità britannica e per il mancato verificarsi della sollevazione popolare egiziana attesa. L'operazione non raggiunse l'obiettivo, ma creò un effetto strategico indiretto costringendo l'Inghilterra a mantenere in Egitto una grande forza.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Emanazione della Legge di Deportazione e Insediamento (Sevk ve İskân / Tehcir)", "2f2bc22c"], "d": ["Dopo la rivolta di Van e l'avanzata russa, il governo emanò la legge provvisoria che permetteva ai comandanti d'armata di trasferire in altre regioni la popolazione ritenuta pericolosa per la sicurezza nelle retrovie, e il sultano la ratificò il 27 maggio 1915. Come conseguenza dell'applicazione, gran parte della popolazione armena delle province orientali e meridionali dell'Anatolia fu avviata in direzione di Siria e Mosul; durante i trasferimenti si ebbero perdite di vite umane molto gravi a causa di malattie, fame e aggressioni. La decisione è rimasta la questione più grave e ancora oggi più controversa degli ultimi anni ottomani.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Le unità ottomane riprendono Muş all'occupazione russa", "fb1be113"], "d": ["Sei mesi dopo la prima occupazione russa di Muş, il XVI Corpo d'armata ottomano entrò nella cittadina nella controffensiva di Bitlis-Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş passa di nuovo in mano russa", "43ad8a03"], "d": ["Per la controffensiva russa il distaccamento ottomano evacuò Muş; la cittadina tra il 22 e il 25 agosto 1916 entrò di nuovo sotto occupazione russa e vi rimase fino alla primavera del 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş liberata definitivamente dall'occupazione russa", "f0e89703"], "d": ["Muş, passata sotto occupazione russa nella Prima guerra mondiale, fu ripresa in modo definitivo dalle forze ottomane il 1° maggio 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Morte di Abdülhamid II nel Palazzo di Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, deposto nel 1909 e portato prima a Salonicco e poi, per la perdita della città nella Guerra balcanica, a Istanbul, dove era tenuto agli arresti nel Palazzo di Beylerbeyi, morì. Nei trentatré anni del suo regno aveva cercato di guadagnare tempo tenendo lo Stato lontano dalle guerre, ma era anche ricordato per il regime dell'istibdat. La salma fu sepolta con una grande folla nel mausoleo di Mahmud I a Divanyolu; la sua morte coincise con un anno di guerra in cui l'ordine da lui creato era da tempo liquidato.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Trattato di Brest-Litovsk: ripresa di Kars, Ardahan e Batum", "da82636f"], "d": ["Il trattato firmato tra la Russia, ritiratasi dalla guerra dopo la rivoluzione bolscevica, e gli Imperi centrali chiuse il fronte orientale e restituì all'Impero ottomano Kars, Ardahan e Batum (Elviye-i Selâse), perduti con il Trattato di Berlino del 1878. Fu l'unico guadagno territoriale ottenuto nella storia ottomana dopo un intervallo di quarant'anni. Ma dopo l'Armistizio di Mudros la regione sarebbe andata di nuovo perduta e la soluzione definitiva sarebbe venuta con il Trattato di Kars del 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Le unità ottomane entrano ad Artvin", "ca7d1778"], "d": ["Le unità ottomane, che il 25 marzo avevano superato il confine del 1914, marciarono sull'Elviye-i Selâse, di cui Brest-Litovsk restituiva il confine anteriore al 1878, ed entrarono ad Artvin il 28 marzo 1918. Artvin era stata lasciata alla Russia nel 1878 come parte del sanjak di Batum; la voce Artvin del TDV scrive il ritorno soltanto come 'marzo 1918', il giorno lo dà Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan passa in mano all'esercito turco", "7fd9e3db"], "d": ["Nell'operazione dell'Elviye-i Selâse l'esercito ottomano prese Ardahan, dopo Artvin, il 3 aprile 1918; Ardahan era caduta nella Guerra del '93 nel 1877 ed era stata lasciata alla Russia nel 1878. Kars sarebbe stata presa un mese dopo, il 25 aprile.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Ripresa di Batum", "d37a1a0d"], "d": ["L'esercito ottomano, avanzato verso est dopo il ritiro della Russia dalla guerra con il Trattato di Brest-Litovsk, riprese dopo quarant'anni il porto di Batum, perduto nel 1878. Questo porto, all'estremità orientale del Mar Nero, era lo sbocco marittimo del petrolio di Baku. Il guadagno durò soltanto sette mesi; dopo l'Armistizio di Mudros la regione sarebbe stata evacuata.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars entra sotto amministrazione ottomana", "02cbf0b3"], "d": ["A Brest-Litovsk fu deciso il ritorno dei tre sanjak perduti con il Trattato di Berlino del 1878 — Kars, Ardahan e Batum; l'esercito ottomano entrò ad Ardahan il 3 aprile, a Batum il 14 aprile, a Kars il 25 aprile 1918 e l'amministrazione fu di fatto stabilita. Questi territori, noti con il nome di 'Elviye-i Selâse', furono considerati la compensazione della perdita in corso dalla Guerra del '93. Dopo l'armistizio sarebbero andati di nuovo perduti e sarebbero stati legati alla Turchia in modo definitivo solo con il Trattato di Kars del 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Presa di Iğdır — avanzata nella valle dell'Aras", "87ebf4d3"], "d": ["Nel quadro dell'operazione in avanti iniziata nel febbraio 1918, le unità turche sconfissero le unità armene a Serderabad, a nord dell'Aras, e presero Iğdır il 20 maggio 1918. Iğdır non faceva parte dell'Elviye-i Selâse, ma era il distretto di Sürmeli del governatorato di Erevan; dopo circa 180 anni fu stabilita nella regione la prima amministrazione ottomana.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Morte di Mehmed V Reşad e ascesa al trono di Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, il cui regno di nove anni era trascorso tra le guerre di Tripolitania, balcaniche e mondiale, morì nel periodo più critico della guerra e al suo posto salì al trono il fratello Vahdeddin con il nome di Mehmed VI. Il nuovo sultano cercò di liberarsi dalla tutela del gruppo unionista; quattro mesi dopo, quando fu firmato l'armistizio, avrebbe dovuto gestire la liquidazione dell'Impero. Fu il trentaseiesimo e ultimo sultano della dinastia ottomana.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Arrivo della flotta dell'Intesa davanti a Istanbul e occupazione di fatto della città", "d10cb14d"], "d": ["Dopo l'Armistizio di Mudros la flotta alleata, composta da oltre sessanta unità di navi inglesi, francesi, italiane e greche, gettò l'ancora davanti a Dolmabahçe e Istanbul passò di fatto sotto occupazione. Dopo quattrocentosessantacinque anni la capitale era per la prima volta sotto il controllo di soldati stranieri. La frase 'Come sono venuti se ne andranno', che si racconta sia stata pronunciata lo stesso giorno da Mustafa Kemal Pascià sbarcato a Haydarpaşa alla vista del panorama, sarebbe divenuta una delle frasi simbolo della Lotta Nazionale.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Ritirata nella regione dell'Aras: evacuata Iğdır", "57572ab4"], "d": ["In conformità alla disposizione dell'Armistizio di Mudros sul ritiro dietro il confine del 1914, Yakup Şevki Pascià con l'ordine del 21 novembre ordinò di ritirare entro il 4 dicembre le unità fuori dal confine di Brest-Litovsk; Iğdır e dintorni furono completamente evacuati a questa data. Poi il Governo Aras-Turco fu rovesciato dagli Armeni alla fine del dicembre 1918.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Gli Inglesi si insediano ad Artvin", "e2cb3153"], "d": ["Poiché l'Armistizio di Mudros del 30 ottobre 1918 imponeva il ritiro dell'esercito ottomano dietro il confine del 1914, Artvin fu evacuata e il 17 dicembre 1918 fu occupata dagli Inglesi. Secondo la voce Artvin del TDV l'occupazione inglese durò fino all'aprile 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Amministrazione britannica a Batum dopo Mudros", "9dd768fc"], "d": ["In forza dell'Armistizio di Mudros del 30 ottobre 1918 l'Impero ottomano fu costretto a ritirarsi da Batum; la città fu occupata il 24 dicembre 1918 dalle unità britanniche. Batum, resa nell'aprile 1918 centro di sanjak autonomo, da questa data fino al luglio 1920 rimase sotto controllo inglese.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan passa sotto dominio georgiano", "97cf47f6"], "d": ["Ardahan, evacuata dopo Mudros, fu occupata dalle forze georgiane il 20 aprile 1919, nei giorni in cui il Governo del Caucaso Sudoccidentale veniva sciolto dagli Inglesi. Il dominio georgiano sarebbe durato fino al 23 febbraio 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston consegna l'amministrazione di Kars al governatore armeno", "efa81cb0"], "d": ["Il comandante inglese Preston, che il 12-13 aprile 1919 sciolse il Governo del Caucaso Sudoccidentale, il 30 aprile 1919 abolì il governo provvisorio dello şûrâ e cedette l'amministrazione della città all'armeno Karganov, fatto governatore di Kars; a Kars iniziò il periodo dell'amministrazione armena, che durò fino alla vittoria di Kâzım Karabekir del 30 ottobre 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Congresso di Erzurum: decisione di resistenza nazionale delle province orientali", "41ef0457"], "d": ["Il congresso convocato dalla Società per la Difesa dei Diritti dell'Anatolia Orientale, dopo un rinvio per pressione inglese, fu aperto con cinquantasei delegati e alla presidenza fu eletto Mustafa Kemal Pascià, che si era dimesso dall'esercito. Il congresso dichiarò che entro i confini nazionali la patria è un tutto, che mandato e protettorato non possono essere accettati e che, in caso di dissoluzione del governo, la nazione avrebbe preso nelle proprie mani il proprio destino. Queste decisioni sei mesi dopo avrebbero costituito il nucleo del testo del Misâk-ı Millî.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Congresso di Sivas: unione della resistenza nazionale sotto un unico tetto", "0e9ad36b"], "d": ["Il congresso, che iniziò i lavori il 4 settembre 1919 nel Sivas Sultânîsi, riunì le società per la difesa dei diritti di ogni parte del paese sotto il nome di Società per la Difesa dei Diritti dell'Anatolia e della Rumelia ed elesse un Heyet-i Temsîliyye (Comitato di Rappresentanza). La proposta di mandato americano fu respinta dopo lunghe discussioni. Con la dichiarazione pubblicata l'11 settembre la Lotta Nazionale divenne un movimento politico legittimo e a centro unico e iniziò una aperta lotta di potere con il governo di Istanbul.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protocollo di Amasya: colloquio del governo di Istanbul con l'Heyet-i Temsîliyye", "40e6a6ab"], "d": ["Dopo la caduta di Damat Ferid e la formazione del governo di Ali Rızâ Pascià, il ministro della Marina Salih Pascià fu inviato ad Amasya per incontrare l'Heyet-i Temsîliyye. Con i protocolli raggiunti il governo di Istanbul riconobbe di fatto l'esistenza del movimento anatolico; furono accettati la convocazione del Meclis-i Meb'ûsan, la libertà delle elezioni e la salvaguardia dei confini nazionali. Fu il primo guadagno politico ufficiale ottenuto dalla Lotta Nazionale di fronte a Istanbul.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Adozione del Misâk-ı Millî nell'ultima Assemblea ottomana", "6322865e"], "d": ["Il testo dell'Ahd-i Millî, firmato da 121 deputati nell'ultimo Meclis-i Meb'ûsan ottomano, richiedeva l'integrità indivisibile dei territori rimasti entro la linea di Mudros e abitati da una maggioranza turco-musulmana, il plebiscito nelle province arabe e in Tracia occidentale, l'abolizione delle capitolazioni e la piena indipendenza politica e finanziaria. Il testo fu adottato all'unanimità il 17 febbraio 1920 e proclamato al mondo. Questa dichiarazione fu non solo il programma politico della Lotta Nazionale ma anche la mappa dei confini che sarebbero stati difesi a Losanna; fu la causa diretta dell'occupazione ufficiale di Istanbul da parte degli Stati dell'Intesa il 16 marzo.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Al ritiro degli Inglesi Artvin resta alla Georgia", "6d086b06"], "d": ["Secondo la voce Artvin del TDV l'occupazione inglese durò fino all'aprile del 1920; ritirandosi gli Inglesi lasciarono la città alla Georgia. Artvin rimase in mano alla Georgia fino all'ultimatum della GANT del 23 febbraio 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum ceduta all'amministrazione georgiana", "6523d095"], "d": ["La consegna ufficiale di Batum da parte degli Inglesi ai Georgiani avvenne il 7 luglio 1920 (la voce Batum del TDV dà soltanto 'luglio 1920'). Il governo di Ankara il 25 luglio protestò contro la cessione definendola 'occupazione'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Trattato di Gümrü: primo trattato internazionale del governo della GANT", "9232c690"], "d": ["Quando l'esercito del fronte orientale al comando di Kâzım Karabekir riprese Sarıkamış e Kars, l'Armenia chiese la pace e con il trattato firmato a Gümrü dichiarò di non riconoscere Sèvres e accettò di rinunciare alle rivendicazioni territoriali a oriente. Questo primo trattato firmato dal governo di Ankara fu il primo documento internazionale a respingere di fatto Sèvres e aprì alla GANT la via del riconoscimento giuridico. Il confine orientale fu così messo in sicurezza e divenne possibile spostare forze sul fronte occidentale.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Prima battaglia di İnönü: prima vittoria dell'esercito regolare", "4add3719"], "d": ["Il nuovo esercito regolare costituito fermò sulle posizioni di İnönü le forze greche che avanzavano in direzione di Bursa e le costrinse a ritirarsi. Questo successo, di scala militare limitata, ebbe conseguenze politiche molto grandi: il governo di Ankara fu invitato alla Conferenza di Londra, si aprì la strada al Trattato di Mosca con la Russia sovietica e fu adottata la Legge di Teşkilât-ı Esâsiyye (Legge sull'Organizzazione Fondamentale). Anche la fiducia dell'opinione pubblica interna nell'esercito regolare si consolidò con questa vittoria.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Seconda battaglia di İnönü: l'attacco greco spezzato per la seconda volta", "a974521c"], "d": ["L'esercito greco, che non aveva ottenuto risultati dalla Conferenza di Londra, passò a un nuovo attacco dalle direzioni di Bursa e Uşak, ma fu fermato di nuovo sulle alture di İnönü e dovette ritirarsi. Il telegramma inviato da Mustafa Kemal Pascià a İsmet Pascià, 'Voi lì non avete vinto soltanto il nemico, ma anche il destino avverso della nazione', fu scritto dopo questa vittoria. La battaglia innalzò il prestigio internazionale della Lotta Nazionale e accelerò il processo di ritiro dell'Italia dall'Anatolia.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Accordo di Ankara: pace con la Francia e chiusura del fronte meridionale", "35fc32db"], "d": ["Con l'accordo firmato ad Ankara con la Francia dopo la vittoria del Sakarya la guerra sul fronte meridionale ebbe fine; le forze francesi evacuarono la Çukurova e il Sud-Est, compresi Adana, Antep, Maraş e Urfa, ritirandosi sul confine siriano. Uno degli Stati dell'Intesa riconobbe così di fatto il governo di Ankara e si aprì la prima crepa sul fronte di Sèvres. Le armi rilevate dalle regioni evacuate e le unità rese libere ebbero un ruolo critico nella preparazione della Grande Offensiva.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Armistizio di Mudanya: cessione senza guerra di Istanbul e degli Stretti", "ac0d9baf"], "d": ["Dopo la Grande Offensiva, con l'esercito turco giunto a fronteggiare le forze inglesi a Çanakkale e a İzmit, la conferenza riunita a Mudanya si concluse con l'armistizio dopo undici giorni di aspre trattative. Fu accettato che la Tracia orientale fino alla Maritza fosse evacuata dalla Grecia entro quindici giorni e consegnata all'amministrazione turca e che Istanbul e gli Stretti fossero consegnati con il trattato di pace. Così la fase armata della Lotta Nazionale si chiuse con una vittoria diplomatica conseguita senza sparare un colpo e si aprì la porta di Losanna.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Partenza di Mehmed VI Vahdeddin da Istanbul ed elezione di Abdülmecid Efendi a califfo", "8ab0e847"], "d": ["Mehmed VI Vahdeddin, ultimo sultano, la cui posizione era divenuta controversa dopo l'abolizione del sultanato, il mattino di venerdì 17 novembre 1922 lasciò Istanbul con la corazzata inglese Malaya e si recò a Malta. La GANT due giorni dopo, il 19 novembre, elesse Abdülmecid Efendi come califfo privo di potere politico. Il governo dinastico ottomano di seicentoventitré anni terminò così di fatto; il califfato sarebbe continuato in forma simbolica per altri quindici mesi. Vahdeddin, passato a Malta e poi in Italia, si stabilì a Villa Nobel a Sanremo; non ottenne risultati dalle richieste fatte per essere accolto in un paese musulmano e morì lì il 16 maggio 1926, ribadendo di non aver mai rinunciato ai diritti di sultanato e califfato.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Morte a Sanremo dell'ultimo sultano Mehmed VI Vahdeddin", "7149ed0e"], "d": ["L'ultimo sultano ottomano Mehmed Vahdeddin, stabilitosi nella città italiana di Sanremo dopo aver lasciato Istanbul, morì il 16 maggio 1926 senza aver saputo della riunione del congresso del califfato (13 maggio 1926), nel quale aveva dichiarato di non aver mai rinunciato ai diritti di sultanato e califfato. Era in gravi difficoltà finanziarie; doveva 60.000 lire ai commercianti di Sanremo e i creditori, saputa della morte, fecero apporre il sequestro ai mobili della sua casa.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Conquista della zona di Bolu da parte di Konuralp — Mudurnu, Konurapa e Bolu", "e245cd27"], "d": ["Konuralp, uno dei comandanti di Orhan Gazi, rivolgendosi alla regione montuosa a est del Sakarya legò all'amministrazione ottomana la zona di Mudurnu, Konurapa e Bolu; la cittadina nella piana di Düzce fu detta con il suo nome. La data esatta della conquista non è nota; il racconto si basa sulla tradizione di Âşıkpaşazâde. La regione era allora un territorio di frontiera che passava di mano tra Candaridi e Bisanzio; la conquista avvicinò per la prima volta gli Ottomani alla costa occidentale del Mar Nero. Dopo la Battaglia di Ankara la zona sarebbe passata di nuovo ai Candaridi, ma sarebbe stata ripresa in modo definitivo al tempo di Maometto il Conquistatore.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Presa dei centri bizantini a sud del Marmara — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Dopo la presa di Nicea e Nicomedia, i centri rimasti in mano bizantina a ovest della piana di Bursa entrarono a uno a uno sotto amministrazione ottomana. Gölyazı attorno al lago di Uluabat, Kirmasti lungo il fiume Susurluk e Mihaliç completarono il corridoio che collegava la costa meridionale del Marmara ai territori di Karesi. Questi centri si arresero a lungo senza vedere un assedio, con l'isolamento dei dintorni; la presenza bizantina nella regione fu così ridotta al golfo di Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Gördüs (Corinto) passa al Despotato di Morea", "392495eb"], "d": ["Corinto, feudo legato al principato d'Acaia della famiglia fiorentina Acciaiuoli dal 1358, nel 1395 passò in mano al despota bizantino di Morea Teodoro. La città da allora rimase sotto l'amministrazione del despotato fino alla conquista ottomana.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Annessione del Beylicato degli Hacıemîroğulları — Ordu e Ünye", "c064f07f"], "d": ["Il beylicato turcomanno fondato da Bayram Bey intorno a Ordu e ampliato negli anni 1350 dal figlio Hacı Emîr era un piccolo ma strategico Stato costiero con centro nell'odierna Eskipazar: era l'unica area di dominio indipendente tra Samsun e Trebisonda. L'emiro Süleyman nel 1398, nella campagna di Canik di Yıldırım Bayezid, aveva dichiarato la propria fedeltà; dopo la Battaglia di Ankara il beylicato era tornato libero. Al tempo di Murad II, negli stessi anni della liquidazione dei Tâceddinoğulları, i territori del beylicato furono legati all'amministrazione ottomana diretta e la costa del Mar Nero da Samsun a Giresun fu riunita in una sola mano.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Conquista di Gördüs (Corinto)", "87a2bc59"], "d": ["Nella campagna di Morea di Maometto il Conquistatore la fortezza di Acrocorinto fu assediata per tre mesi e alla fine ricevuta in resa per via pacifica. L'istmo di Corinto, considerato la porta della Morea, passò così agli Ottomani.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Annessione del Montenegro all'amministrazione ottomana — Cetinje", "7fdb7cc8"], "d": ["Quando la dinastia Crnojević, che governava Zeta, abbandonò il dominio nel 1496, la regione montuosa del Montenegro, retrovia di Scutari, fu posta sotto amministrazione ottomana diretta e fu organizzata dapprima come sanjak separato, poi come parte del sanjak di Scutari. Il monastero di Cetinje fu lasciato al suo posto come centro religioso della regione. Per la durezza della geografia l'amministrazione qui non funzionò mai in modo così stretto come nelle pianure; due secoli dopo il governo dei vladika nato dallo stesso monastero sarebbe stato il nucleo dell'indipendenza di fatto.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["La fortezza di Bayezid accetta il dominio ottomano nella Campagna dei Due Iraq", "f29e2e17"], "d": ["Quando il gran visir İbrahim Pascià, nella Campagna dei Due Iraq, giunse nei dintorni di Bingöl, insieme a molte tribù curde della regione le fortezze di Van, Toprakkale, Avnik e Bayezid accettarono di entrare sotto il dominio ottomano. Bayezid si era unita agli Ottomani nel 1514 nella campagna di Selim il Severo, ma al ritorno dell'esercito i Safavidi avevano ripreso la regione.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz passa di nuovo ai Safavidi — il ritorno dell'Irakeyn", "80b8b761"], "d": ["Nella Campagna dei Due Iraq l'esercito era entrato a Tabriz, ma, poiché l'obiettivo principale era Baghdad, in città non era stata lasciata una guarnigione stabile. Mentre l'esercito, che aveva passato l'inverno a Baghdad, tornava a ovest, lo shah Tahmasp rientrò nell'Azerbaigian evacuato e riprese Tabriz. Questo era lo schema ricorrente delle guerre ottomano-safavidi: Tabriz fu presa cinque volte e in tutte e cinque non poté essere tenuta; la città avrebbe avuto una guarnigione ottomana di lunga durata solo nel 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van ed Erciş cadono nelle mani di Tahmasp (la posizione ottomana terminò nel 1534-35)", "cb93d561"], "d": ["Nella regione che aveva dato Van al dominio ottomano nel 1534, Ulama Pascià resistette nella fortezza di Van all'assedio safavide; la fortezza passò in mano safavide e anche le forze safavidi che assediavano Erciş si erano ritirate con l'aiuto ottomano. Quando Solimano il Legislatore giunse ad Ahlat (23 settembre 1535) Van era ormai in mano a Tahmasp. Van rimase safavide fino al 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Il sanjak di Bayezid passa sotto dominio safavide (Van ed Erciş erano già safavidi nel 1535)", "806a2cf1"], "d": ["Il sanjak di Bayezid, a metà del confine ottomano-safavide, passò di nuovo in mano iraniana (Kaya 2017 lo ricorda 'insieme a Van ed Erciş'; ma Van ed Erciş secondo Karataş 2025 e TDV erano tornate ai Safavidi il 22 settembre 1535 — cfr. voce precedente); in questo cambio di mano alcuni luoghi del sanjak furono devastati. Il sanjak cambiò di mano ripetutamente tra i due Stati fino all'ultimo quarto del XVI secolo.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Il sanjak di Bayezid passa di nuovo agli Ottomani durante la Campagna di Nakhchivan", "cf0171fa"], "d": ["Durante la terza campagna d'Iran (Nakhchivan) di Solimano il Legislatore il sanjak di Bayezid fu posto di nuovo sotto amministrazione ottomana. Nella campagna del 1554 Bayazıt fu un'importante base per l'esercito; il sanjak entrò in modo definitivo sotto sovranità ottomana nel 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Perdita di Erevan a favore di Shah Abbas", "34413cf2"], "d": ["Quando, negli anni in cui le rivolte celâli bloccavano l'Anatolia, il fronte orientale rimase indifeso, Shah Abbas, che aveva riorganizzato il suo esercito all'europea, passò all'attacco. La fortezza di Erevan, fatta costruire da Ferhad Pascià nel 1583, dopo un assedio di sette mesi si arrese. Il primo anello della linea caucasica guadagnata con il Trattato di Ferhad Pascià si era spezzato e nei tre anni successivi tutto il Caucaso meridionale sarebbe andato perduto.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Perdita di Tiflis e Ganja", "3fb51753"], "d": ["Dopo la caduta di Erevan l'esercito safavide avanzò lungo la valle del Kura; Ganja, centro del Karabakh, e Tiflis, capitale della Georgia, andarono perdute una dopo l'altra. L'Impero ottomano conduceva contemporaneamente sul fronte austriaco la lunga guerra di tredici anni e in Anatolia era alle prese con i Celâli; non c'erano forze da inviare a oriente. Così l'ordinamento delle ampie province caucasiche stabilito con il Trattato di Ferhad Pascià del 1590 ebbe fine di fatto.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Perdita dello Shirvan — Shamakhi, Baku e Derbent", "81beab11"], "d": ["La provincia dello Shirvan sulla costa del Caspio, guadagnata con le campagne di Özdemiroğlu Osman Pascià del 1578-1585, aveva fornito alle finanze ottomane un reddito importante come principale fonte del commercio della seta. L'operazione di Shah Abbas verso nord, prendendo di seguito Shamakhi, Baku e Derbent, liquidò questa provincia. La perdita non fu solo territoriale: anche la via con cui la seta iraniana affluiva in Europa attraverso gli Ottomani uscì dal controllo e lo Stato safavide cominciò a commercializzare la seta attraverso l'Oceano Indiano.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Perdita di Taiz", "65f20d53"], "d": ["Nel 1038 (1629) gli Ottomani abbandonarono Taiz insieme al dominio sullo Yemen, lasciato all'amministrazione qasimide di Sana'a — il primo grande passo del processo con cui gli imam zaiditi ripresero l'interno dello Yemen.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Perdita dello Yemen — dominio degli imam qasimidi", "49e83e3c"], "d": ["Lo Yemen era provincia ottomana dal 1538; ma la resistenza degli imam zaiditi non cessò mai. La rivolta avviata dall'imam Qasim si estese a tutto il paese al tempo del figlio al-Mu'ayyad Muhammad e le guarnigioni ottomane furono assediate una dopo l'altra. Negli anni in cui Murad IV era concentrato su Baghdad ed Erevan non si poterono inviare rinforzi; Taiz era andata perduta nel 1629, mentre Mocha era stata evacuata nell'ultima fase dello stesso crollo, il 22 ottobre 1635. Nel 1635 anche le ultime unità a Sana'a e Zabid evacuarono lo Yemen. Così la costa orientale del Mar Rosso rimase fuori dall'Impero per duecentotrentasette anni, poté essere ripresa solo nel 1872. Lahej (al-Hawta), secondo il TDV İslâm Ansiklopedisi, fu in mano agli Ottomani fino al 1635; da quella data ebbero influenza gli imam zaiditi.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Evacuazione di Mocha", "c6b3061a"], "d": ["Mustafa Bey il 10 Cemâziyelevvel 1045 (22 ottobre 1635) evacuò Mocha con le forze e le armi rimaste; poi Hasan b. Qasim, figlio dell'imam Qasim, nominando propri uomini a Zabid e Mocha, stabilì il controllo qasimide anche sulla costa della Tihama.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Perdita di al-Hasa a favore dell'Emirato dei Banu Khalid", "a9b6131a"], "d": ["Al-Hasa era una provincia istituita nel 1550 per chiudere al Portogallo la costa occidentale del Golfo di Bassora; ma era lontanissima da Istanbul, all'estremità di un'unica via del deserto. Negli anni in cui l'assedio di Creta esauriva le risorse, la tribù dei Banu Khalid della regione, guidata da Barrak b. Ghurayr, cacciò la guarnigione ottomana e fondò un proprio emirato. La costa occidentale del Golfo rimase per un secolo e mezzo negli emirati tribali; nel 1795 sarebbe passata ai Sauditi, nel 1871 di nuovo agli Ottomani.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Perdita di Prevesa e Vonitsa a favore di Venezia — apertura della costa dell'Epiro", "1201204c"], "d": ["Venezia, entrata nella Lega Santa, prima di iniziare la campagna di Morea prese le due fortezze che tengono l'imboccatura del golfo di Arta: Prevesa e, sulla riva opposta, Vonitsa. Nella stessa estate era caduta anche Ayamavra (Leucade). Queste tre posizioni permisero di introdurre in sicurezza la flotta dal Mar Ionio nell'interno della Grecia e divennero la base della campagna di Morea che sarebbe iniziata l'anno seguente. Prevesa e Vonitsa furono lasciate a Venezia anche a Passarowitz; sarebbero tornate sotto amministrazione ottomana solo nel 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Perdita di Szolnok — dissoluzione della linea del Tibisco", "51c2c8ef"], "d": ["Dopo la caduta di Uyvar in agosto l'esercito asburgico si volse a sud e prese Szolnok, testa di ponte sul fiume Tibisco. La città era l'unico passaggio sicuro tra Buda e la Transilvania; la sua perdita significava la separazione tra loro delle fortezze ottomane nella metà orientale dell'Ungheria. Fu determinante, l'anno seguente, nell'assedio di Buda, il fatto che la via dei rifornimenti fosse tagliata.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Perdita di Modone a favore di Venezia", "114c9cc0"], "d": ["Modone, all'estremità sudoccidentale della Morea, era il porto che Venezia aveva perduto tre secoli prima e che chiamava 'uno dei due occhi dello Stato'. La fortezza, assediata dopo la caduta di Corone, fu battuta contemporaneamente da terra e da mare e ricevuta in resa. La campagna di Morea di Morosini prese così tutta la costa occidentale della penisola e si aprì la via verso l'interno.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Perdita di Peçuy", "99d54cf4"], "d": ["Dopo la caduta di Buda a settembre le forze asburgiche scesero a sud, a ovest del Danubio, e presero Peçuy, ottomana dal tempo di Solimano il Legislatore. La città, ricordata con la moschea di Gazi Kâsım Pascià, era uno dei centri di sanjak più sviluppati dell'eyalet di Buda. La sua perdita significava l'apertura della via che scende nella piana di Mohács; l'anno seguente la Seconda disfatta di Mohács si sarebbe verificata proprio qui.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Perdita di Seghedino", "9fbee1b2"], "d": ["Seghedino, alla confluenza dei fiumi Tibisco e Maros, era la porta meridionale della pianura ungherese e teneva la via per l'eyalet di Timișoara. La fortezza, assediata dopo la caduta di Buda e Peçuy nello stesso autunno, si arrese in breve tempo. La perdita di tre fortezze in una stagione fu il segno che la struttura amministrativa ottomana in Ungheria, stabilita dal 1541, cominciava a crollare. L'atlante considera nello stesso giorno passata dagli Ottomani agli Asburgo anche Zenta sul Tibisco (il giorno di resa specifico di Zenta non è stato letto nella fonte, il giorno è preso da Seghedino; TDV zenta: dall'ottobre 1686 iniziarono scontri tra gli Ottomani e gli alleati guidati dagli Asburgo — beyanlı yaklaşıklık).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Perdita di Balyabadra (Patrasso) — la porta settentrionale della Morea", "b9cff63c"], "d": ["Balyabadra, all'imboccatura del golfo di Corinto, era il porto che controllava il passaggio tra Morea e Rumelia. Dopo che l'esercito veneziano ebbe preso la città, caddero una dopo l'altra anche le fortezze sulle due rive del golfo e la penisola fu completamente isolata da terra. Alla fine di questa campagna tutta la Morea passò a Venezia; la regione fu governata fino al 1715 con il nome di 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Gördüs (Corinto) lasciata a Venezia", "9a25b6b9"], "d": ["Dopo la caduta di Balyabadra Corinto fu lasciata ai Veneziani per via pacifica e la popolazione musulmana abbandonò la città. Nell'agosto 1687 l'esercito di Morosini si raccoglieva a Corinto per la campagna di Atene.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Perdita di Eger", "983391aa"], "d": ["Eger era stata presa nel 1596 con la campagna a cui partecipò personalmente Mehmed III ed era divenuta centro di un eyalet con il proprio nome. Questa ultima grande fortezza ottomana dell'Ungheria settentrionale, completamente assediata dopo la Seconda disfatta di Mohács, resistette un anno e si arrese per la fame. Con la sua perdita il fianco settentrionale dell'Impero ottomano in Ungheria fu interamente liquidato.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Perdita di İstolni Belgrad (Székesfehérvár) — la città dell'incoronazione dei re ungheresi", "c6147255"], "d": ["La città in cui per secoli furono incoronati e sepolti i re ungheresi era stata presa nel 1543 da Solimano il Legislatore ed era divenuta uno dei più importanti centri di sanjak dell'eyalet di Buda. Circa due anni dopo la caduta di Buda la fortezza, completamente isolata, si arrese. Con questa perdita la presenza ottomana a ovest del Danubio fu ridotta ai dintorni di Sirmio e Osijek.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Perdita di Szigetvár", "834910a7"], "d": ["Szigetvár era la fortezza in cui Solimano il Legislatore morì nel 1566, durante l'assedio, nella tredicesima e ultima campagna; per questo aveva un posto simbolico nella memoria ottomana. Centoventitré anni dopo, caduta ogni fortezza circostante, si arrese anche la fortezza protetta dalle paludi. Il mausoleo in cui erano sepolte le viscere di Solimano e la cittadina circostante furono distrutti dopo il passaggio all'amministrazione asburgica. Aynı tarihte atlasta Osmanlı'dan Habsburg'a geçen diğer yerleşim: Barcs — Zigetvar'ın abi-merkez zincirini izler (Bánlaky 0017/1449; beyanlı yaklaşıklık).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Perdita di Varad", "6cce360d"], "d": ["Varad era la fortezza chiave verso la Transilvania presa nel 1660 da Köprülü Mehmed Pascià e fatta centro di un eyalet con il proprio nome. Rimasta del tutto sola dopo la disfatta di Slankamen, la fortezza, dopo un blocco durato quasi due anni, si arrese per la fame. Con la sua perdita l'influenza ottomana sulla Transilvania ebbe fine di fatto e il dominio asburgico si stabilì a est del Tibisco.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Perdita di Yanova — chiusura della via di Transilvania", "4b5e30d8"], "d": ["Yanova era una fortezza presa nel 1658 che teneva il collegamento tra Varad e Timișoara. Subito dopo la caduta di Varad, isolata, andò perduta anch'essa. Così l'eyalet di Timișoara fu completamente isolato da nord e fino a Karlowitz continuò a esistere come unico territorio ungherese rimasto in mano ottomana.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Istituzione del governo dei vladika in Montenegro — distacco di fatto di Cetinje", "a924b778"], "d": ["Negli anni in cui la Guerra della Lega Santa allentava il controllo ottomano nei Balcani, il metropolitato a capo del monastero di Cetinje divenne una carica trasmessa di padre in figlio nella famiglia Petrović e la regione acquisì di fatto un'amministrazione separata. Grazie all'inaccessibilità dei monti questo vladikato per due secoli continuò a esistere in una condizione né pienamente indipendente né pienamente legata; la sua indipendenza giuridica sarebbe stata riconosciuta solo con il Trattato di Berlino del 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Ripresa di Gördüs (Corinto)", "26f53e3a"], "d": ["La prima grande tappa della campagna di Morea di Damad Ali Pascià fu Corinto; gli Ottomani nel giugno 1715 ripresero la città ai Veneziani e da qui avanzarono verso il resto della penisola.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Offensiva di Nadir: perdita di Tabriz, Nakhchivan, Hamadan, Kermanshah, Marāgheh e Qasr-i Şîrîn", "d95efd59"], "d": ["Le città dell'Iran occidentale prese tra il 1723 e il 1727 approfittando del crollo dello Stato safavide andarono perdute una a una con l'offensiva di Nadir Khan, che aveva preso il potere di fatto in Iran. In Azerbaigian anche Ardabil e Khalkhal passarono a Nadir. La perdita di Hamadan, Kermanshah e Qasr-i Şîrîn ebbe grande eco a Istanbul; il fatto che l'esercito non partisse in campagna ma attendesse a Üsküdar e che si cercasse di occultare la perdita fu una delle cause dirette della Rivolta di Patrona Halil scoppiata sei settimane dopo. L'atlante considera passata in questo giorno dagli Ottomani ai Safavidi anche Kotur, che segue la catena di Hoy (Uluerler 2015, Turkish Studies 10/5, p. 6; Kotur'a özgü gün kaynakta yok — beyanlı yaklaşıklık).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Disfatta di Baghavard (Arpaçay) — perdita del Caucaso a favore di Nadir Khan", "4262f54c"], "d": ["Le province caucasiche prese nel 1723-1725 approfittando del crollo dello Stato safavide poterono essere tenute dieci anni. Nadir Khan, che aveva preso il potere di fatto in Iran, inflisse una grave sconfitta all'esercito ottomano a Baghavard, presso Erevan; il serdar Abdullah Köprülü Pascià perse la vita sul campo di battaglia. Dopo la disfatta Erevan, Tiflis, Ganja e lo Shirvan furono evacuate nel giro di mesi. Il confine orientale tornò alla linea di Qasr-i Şîrîn del 1639, come sarebbe stato confermato nel 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Perdita di Bender a favore dei Russi", "0daca453"], "d": ["Dopo la disfatta della piana di Kartal l'esercito ottomano si era ritirato a sud del Danubio e le fortezze tra Moldavia e Özi erano rimaste sole. Bender, che teneva il punto di passaggio del fiume Turla, fu presa d'assalto dopo un assedio di due mesi; la città fu saccheggiata. La perdita della fortezza spezzò l'anello centrale della linea di difesa del Mar Nero settentrionale, dopo di che caddero anche Akkerman e Kilia. A Küçük Kaynarca Bender sarebbe stata restituita, ma nel 1806 sarebbe stata perduta di nuovo.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["L'emirato Sabah del Kuwait entra sotto la protezione ottomana", "3584dba0"], "d": ["Secondo la voce Kuwait del TDV lo scalo era stato fondato all'inizio del XVIII secolo dalla tribù degli Utub provenienti dal Najd e la famiglia Sabah aveva preso l'amministrazione verso la fine del secolo. Negli stessi anni in cui al-Hasa passava ai Sauditi, l'emirato, che di fronte alla pressione wahhabita non aveva altra scelta che appoggiarsi a Bassora, entrò sotto la protezione ottomana. Il legame sarebbe stato formalizzato nel 1871 con il riordino di Bassora di Midhat Pascià e il Kuwait sarebbe stato considerato uno dei tre kaza del sanjak di Bassora; anche la successiva rivendicazione territoriale dell'Iraq si basa su questa registrazione.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Perdita della Mecca a favore dei wahhabiti", "2da23acd"], "d": ["Il movimento wahhabita, nato nel Najd, si volse all'Hijaz al tempo di Saud b. Abd al-Aziz; dopo Ta'if e Medina anche la Mecca fu ricevuta in resa per la seconda volta — l'emiro della Mecca sharif Ghalib consegnò la città ai wahhabiti a condizione di restare nell'emirato. I mausolei furono abbattuti e la via delle carovane di pellegrini da Damasco e dal Cairo fu tagliata; anche il surre che il sultano inviava ogni anno ai Haramayn fu interrotto in questi anni — l'unica eccezione a questa assegnazione ininterrotta fino al 1915 è il periodo del dominio wahhabita. Poiché il titolo di protettore dei Haramayn era uno dei pilastri fondamentali della legittimità del sultano, questa perdita fu, oltre che territoriale, un grave colpo politico; la ripresa sarebbe durata sette anni e sarebbe stata possibile con l'esercito di Mehmed Ali Pascià di Kavala.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Fine della Repubblica di Ragusa (Dubrovnik) — occupazione francese", "f8e27bf1"], "d": ["I Francesi, stabilitisi sulla costa dalmata con il Trattato di Campoformio (1797), il 27 maggio 1806 presero Dubrovnik e posero fine alla piccola repubblica mercantile. Così terminò lo status di dipendenza di tre secoli e mezzo di Dubrovnik, che dal 1458 pagava tributo agli Ottomani preservando l'autonomia e i privilegi commerciali; la città e l'isola di Mljet della repubblica sulla mappa passano direttamente all'amministrazione francese.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Perdita di Sukhum a favore dei Russi — apertura della costa orientale del Mar Nero", "adc96bd4"], "d": ["Nella guerra ottomano-russa del 1806-1812 la flotta russa si volse alla costa orientale del Mar Nero e prese Sohumkale, su cui poggiava il dominio ottomano in Abcasia. La fortezza era il centro del collegamento con le tribù caucasiche e del commercio costiero. Con la sua perdita la Russia si stabilì per la prima volta in modo permanente sulla costa orientale del Mar Nero; l'influenza ottomana nel Caucaso fu ridotta alle zone di Anapa e Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Parga lasciata all'amministrazione ottomana", "66e0cc5d"], "d": ["Parga era in mano a Venezia dal 1401 e non era mai entrata sotto amministrazione ottomana; dopo la caduta di Venezia passò in successione alla Francia e all'Inghilterra. La voce Tepedelenli Ali Paşa del TDV riassume la situazione così: la città si arrese agli Inglesi e fu ceduta all'amministrazione di Ali Pascià solo nel 1819. La cessione si concluse con l'emigrazione di gran parte della popolazione nelle isole Ionie. Così anche l'ultimo del trio Prevesa-Parga-Vonitsa, lasciato a Venezia a Passarowitz, fu aggregato all'Impero; Parga sarebbe rimasta ottomana per novantaquattro anni.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Gördüs (Corinto) passa ai ribelli greci", "892dcdc6"], "d": ["Durante la guerra d'indipendenza greca Acrocorinto passò in mano ai ribelli e il comandante della fortezza Kâmil Bey fu fatto prigioniero.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Perdita di Anabolu (Nauplia) a favore dei ribelli", "1a67fa50"], "d": ["Anabolu, porto con la fortificazione più forte della Morea, si arrese per la fame dopo un blocco di oltre un anno. La fortezza era dall'inizio della rivolta l'ultimo grande appoggio del controllo ottomano nella penisola; con la sua perdita tutta la Morea passò in mano ai ribelli. La città sarebbe divenuta poco dopo la prima capitale del nuovo Stato greco.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Passaggio di Lepanto (İnebahtı) all'amministrazione greca", "c9d19d4b"], "d": ["Lepanto, sulla costa settentrionale del golfo di Corinto, rimasta in mano ottomana fino alla rivolta greca, andò perduta nell'aprile 1829 ed entrò sotto amministrazione greca; il nome della cittadina fu cambiato nell'antico Naupatto (Nafpaktos). La popolazione musulmana ed ebraica della città scomparve del tutto e questa si trasformò in una piccola cittadina.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Occupazione francese di Algeri — fine dell'ocak di trecento anni", "0be8f568"], "d": ["Con il pretesto dell'episodio del ventaglio nato da una controversia su un credito, la Francia tenne per tre anni sotto blocco la costa algerina, poi sbarcò truppe a Sidi Ferruch. Al termine di un'operazione di tre settimane Hüseyin Dey si arrese e l'Ocak ottomano di Algeri, in vita dal 1516, ebbe fine. L'occupazione non rimase limitata alla capitale; anche Tlemcen, Cherchell e Medea nell'interno andarono perdute nella stessa estate. L'ingresso dell'intera costa sotto controllo francese avrebbe richiesto altri ventiquattro anni.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Cessione di Negroponte (Eğriboz) alla Grecia — con l'isola (Caristo, Oreoi)", "7b524aa4"], "d": ["Negroponte, teatro di intensi combattimenti durante la guerra d'indipendenza greca ma rimasta in mano ottomana, fu data ai Greci nel 1831 dopo l'entrata in vigore del trattato di pace. La popolazione musulmana della città, importante base navale dal 1470, vendendo tutti i beni a prezzi bassissimi emigrò in massa in territorio ottomano; la città rimase a lungo vuota e il viaggiatore tedesco Fallmerayer nel 1842 la definì una città fantasma.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Occupazione francese di Orano (Vehrân)", "a8415d66"], "d": ["Orano, ceduta senza guerra dalla Spagna nel 1792, era il più grande porto dell'Algeria occidentale. Sei mesi dopo la caduta della capitale le truppe francesi entrarono in città. L'operazione verso ovest partita da qui si sarebbe presto scontrata con la resistenza quindicennale dell'emiro Abd al-Qadir.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Occupazione di Annaba (Bona)", "21f37fb1"], "d": ["Annaba, porto dell'Algeria orientale vicino al confine tunisino, fu presa dalle forze francesi e fatta base della marcia su Costantina. La città era anche il porto africano più vicino di fronte all'isola di Sardegna.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Cessione di Atene al nuovo Stato greco (giorno in cui le unità bavaresi presero in consegna l'Acropoli)", "deee4d37"], "d": ["Atene, ottomana dal 1456, durante la guerra d'indipendenza greca era passata di mano più volte e la guarnigione sull'Acropoli era tornata sotto controllo ottomano nel 1827. Poiché si trovava a nord del confine tracciato dal Protocollo di Londra, la città fu ceduta al nuovo regno e la guarnigione evacuò l'Acropoli. Il giorno dell'atlante è quello in cui le unità bavaresi presero in consegna l'Acropoli; l'uscita di fatto della guarnigione ottomana avvenne alcuni giorni dopo (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, cap. 13; Finlay, Journals and Letters, vol. I, p. 67). L'anno seguente Atene fu proclamata capitale della Grecia al posto di Anabolu.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Occupazione di Bugia (Bicâye)", "a8927e00"], "d": ["Il porto di Bugia, dove le montagne della Cabilia si aprono sul mare, era l'ultimo anello indipendente della linea costiera tra Algeri e Annaba. Fu preso con il sostegno dell'artiglieria navale; ma l'interno montuoso alle sue spalle non sarebbe entrato sotto controllo francese per altri trent'anni. Queste occupazioni lungo la costa costituiscono lo sciogliersi anno per anno sulla mappa dell'Algeria ottomana.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Occupazione di Sétif", "2073731a"], "d": ["Dopo la caduta di Costantina un anno prima, le forze francesi salirono sull'altopiano e, prendendo l'antica città romana di Sétif, vi stabilirono una guarnigione permanente. Sétif era il punto di incrocio delle vie carovaniere tra la costa e il Sahara; la sua occupazione mostrò che la Francia cominciava a controllare non più solo i porti ma anche la rete commerciale interna.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Occupazione di Biskra — perdita della porta del Sahara", "d895cad0"], "d": ["Biskra era, ai piedi meridionali dei monti dell'Atlante, la porta che si apre sul Sahara e il centro delle oasi di palme da dattero. Con la sua presa negli anni in cui la resistenza dell'emiro Abd al-Qadir cominciava a spezzarsi, il controllo francese raggiunse per la prima volta la sponda settentrionale del deserto. Da allora in poi sarebbe stata una campagna del deserto che avanzava oasi per oasi.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Occupazione di Touggourt — perdita dell'intera Algeria", "33c056e2"], "d": ["Con la presa di Touggourt, città-oasi a nord del Sahara, l'occupazione iniziata nel 1830 si completò nella metà settentrionale dell'odierna Algeria. L'Impero ottomano in questi anni combatteva nella Guerra di Crimea sullo stesso fronte della Francia; pur senza aver mai rinunciato ufficialmente alla propria pretesa giuridica sull'Algeria, di fatto non poté compiere un solo passo. L'unico territorio rimasto in Nordafrica era la Tripolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Caduta di El Obeid — il Kordofan passa alle forze del Mahdi", "58299f62"], "d": ["Il movimento avviato da Muhammad Ahmad, che si proclamò mahdi, si diffuse rapidamente contro l'amministrazione egiziana del Sudan. El Obeid, centro del Kordofan, cadde dopo un assedio di quattro mesi e divenne capitale della rivolta; il tesoro e i depositi d'armi della città permisero al movimento di organizzarsi in esercito. Il Sudan era giuridicamente ancora territorio del khedivato d'Egitto legato agli Ottomani, dunque la perdita cade sulla mappa dal corpo dell'Impero.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Caduta di Khartum — perdita dell'intero Sudan", "d4b98464"], "d": ["Dopo un assedio di dieci mesi le forze del Mahdi entrarono a Khartum, al punto di confluenza tra Nilo Azzurro e Nilo Bianco; il governatore della città, Gordon, fu ucciso e la colonna britannica inviata in soccorso arrivò con due giorni di ritardo. Da questa data l'intero Sudan, compresi Sennar, Dongola e Kordofan, rimase per quattordici anni sotto l'amministrazione dello Stato del Mahdi. La regione sarebbe entrata solo nel 1899 nell'amministrazione congiunta anglo-egiziana, con il legame ottomano completamente reciso.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Occupazione italiana di Massaua — perdita della costa occidentale del Mar Rosso", "c333b95b"], "d": ["Il porto di Massaua, centro dell'eyalet di Abissinia, fu occupato dall'Italia, che approfittava della confusione in cui la rivolta del Mahdi aveva immerso il Sudan; ciò costituì il nucleo dell'Eritrea italiana. Anche Suakin a nord e l'arcipelago di Dahlak al largo andarono perduti nello stesso processo. Così ebbe fine il dominio ottomano sulla costa occidentale del Mar Rosso, in vigore dal tempo di Selim il Severo, e il mare divenne ormai acqua straniera su entrambe le sponde.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Occupazione italiana di Rodi", "e08662c5"], "d": ["Nella Guerra di Tripolitania l'Italia, che voleva far sedere al tavolo l'Impero ottomano, portando la guerra nel Mediterraneo sbarcò truppe a Rodi. L'isola fu presa in pochi giorni. Rodi, che Solimano il Legislatore aveva preso nel 1522 con un lungo assedio e che era rimasta in mano ottomana per trecentonovant'anni, cessò così di essere la maggiore base insulare dell'Impero nel Mediterraneo orientale; pur considerata occupazione temporanea nel Trattato di Ouchy, non poté più essere ripresa.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Occupazione italiana del Dodecaneso", "200aacf2"], "d": ["Entro una settimana dalla presa di Rodi la flotta italiana occupò anche le isole circostanti; in seguito questo arcipelago sarebbe stato chiamato 'Dodecaneso'. La maggior parte delle isole era a poche miglia dalla costa anatolica e controllava il passaggio sudorientale dell'Egeo. L'occupazione fu considerata temporanea nel Trattato di Ouchy in cambio della cessione della Tripolitania, ma l'Italia non evacuò mai le isole; sarebbero state cedute alla Grecia nel 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Occupazione di Coo", "ab246c62"], "d": ["Coo, ultimo anello dell'operazione del Dodecaneso, era un'isola fertile e popolosa proprio di fronte alla penisola di Bodrum. Con l'occupazione tutte le isole nell'angolo sudorientale dell'Egeo passarono sotto controllo italiano e la costa sudoccidentale dell'Anatolia fu circondata da un capo all'altro da una catena di isole straniere.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Dichiarazione d'indipendenza di Nikarya", "c4452033"], "d": ["Sulla piccola isola di Nikarya, tra Samo e Chio, la popolazione, nel clima di incertezza creato dalle occupazioni italiane, si sollevò, cacciò dall'isola la gendarmeria ottomana e proclamò uno 'Stato libero' durato cinque mesi con propria bandiera, francobolli e assemblea. Nel novembre 1912 l'isola si unì alla Grecia. Nonostante le dimensioni ridotte, questo episodio è un chiaro indicatore di come si stesse dissolvendo l'amministrazione centrale nell'Egeo.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Uscita di Samo dall'amministrazione ottomana", "3a862f2b"], "d": ["Samo era un principato autonomo dal 1832, tributario degli Ottomani e governato da un bey nominato da Istanbul. Nel vuoto creato dalla Guerra di Tripolitania il movimento unionista sull'isola prese l'amministrazione e l'ordinamento del principato autonomo cessò di fatto; l'isola nello stesso anno dichiarò l'unione alla Grecia. Quest'isola, a due chilometri dalla costa anatolica, fu uno dei primi territori perduti nell'Egeo.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Caduta di Ioannina — perdita dell'Epiro e di Parga", "d42fce18"], "d": ["Ioannina, assediata per cinque mesi nella Guerra balcanica, si arrese dopo la caduta delle posizioni di Bizani; con la città tutto l'Epiro passò alla Grecia. Anche Parga, dipendente dal sanjak di Ioannina, andò perduta a questa data e l'amministrazione ottomana di novantaquattro anni ebbe fine. La perdita di Ioannina significava la chiusura dell'ultima finestra dell'Impero sull'Adriatico.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Caduta di Edirne ai Bulgari", "459d2e56"], "d": ["Dopo un assedio di cinque mesi e mezzo, esaurite munizioni e viveri, Edirne si arrese; Şükrü Pascià fu fatto prigioniero. La caduta della città, ottomana dal 1361 e capitale per novantadue anni, fu considerata il colpo più grave della Guerra balcanica. Edirne sarebbe stata ripresa quattro mesi dopo, approfittando del crollo della Bulgaria sugli altri fronti nella Seconda guerra balcanica.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Perdita di Yanbu a favore delle forze di Sharif Husayn", "e291c816"], "d": ["La rivolta avviata a giugno da Sharif Husayn si estese alla costa del Mar Rosso; Yanbu, porto di Medina, con il sostegno della flotta inglese passò in mano ai ribelli. Il porto divenne la principale porta del flusso di armi e denaro che giungeva dall'esterno alla rivolta. Così il collegamento con il mare delle forze di Fahreddin Pascià a Medina fu tagliato e la città rimase sola all'estremità della ferrovia dell'Hijaz.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Terza battaglia di Gaza — perdita di Gaza e Khan Yunis", "c142a069"], "d": ["Dopo due tentativi falliti Allenby nel suo terzo attacco sfondò il fronte aggirando da Beersheba e la linea di Gaza, tenuta per sei mesi, crollò. Gaza e Khan Yunis, a sud, furono evacuate lo stesso giorno. Questo sfondamento fu l'inizio della dissoluzione del fronte di Palestina; Gerusalemme sarebbe caduta cinque settimane dopo.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Occupazione di Komotini (Gümülcine) — perdita della Tracia occidentale", "904d813c"], "d": ["La Tracia occidentale, passata dopo Mudros sotto il controllo delle forze dell'Intesa, fu lasciata alla Grecia con la decisione della conferenza di San Remo e l'esercito greco entrò a Komotini. La regione, ripresa alla Bulgaria nel 1913, fu l'ultimo territorio perduto dall'Impero in Rumelia. Lo status della popolazione turca della regione sarebbe stato regolato tre anni dopo a Losanna con il regime delle minoranze. Con questa occupazione i kaza di Komotini, Xanthi, Dedeağaç e Sofulu della Tracia occidentale passarono alla Grecia.", "ef0aeba3"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemia di peste a Istanbul e trasferimento del palazzo a Edirne", "70c7a163"], "d": ["Secondo la voce Istanbul del TDV İslâm Ansiklopedisi, il rapido e intenso popolamento della città preparò di tanto in tanto il terreno alla diffusione di malattie epidemiche; durante l'epidemia di peste del 1466 il palazzo e i dignitari dello Stato si ritirarono temporaneamente a Edirne. La popolazione della città subì perdite gravi in simili epidemie.", "7b20238c"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Apertura all'insegnamento delle madrase Sahn-ı Semân", "021f2a83"], "d": ["Secondo la voce Sahn-ı Semân del TDV İslâm Ansiklopedisi queste otto madrase, fondate nell'ambito del Complesso di Fatih, furono concepite come l'istituzione di insegnamento di livello più alto dell'epoca e costituirono il vertice della gerarchia ottomana dell'ilmiye. L'insegnamento qui e il diploma furono considerati nei secoli successivi il gradino più prestigioso nella carriera di kadı e müderris.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Completamento del Palazzo di Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Secondo la voce Topkapı Sarayı del TDV İslâm Ansiklopedisi le fonti dell'epoca divergono sulle date di inizio e fine dei lavori; secondo la data 883 (1478) dell'iscrizione della Bâb-ı Hümâyun, la costruzione, iniziata probabilmente nel 1465 per ordine di Maometto il Conquistatore, era in gran parte completata entro quest'anno e il palazzo sostituì il centro dello Stato nel vecchio palazzo. Così il sultano si trasferì nella nuova residenza che per tre secoli sarebbe stata il cuore amministrativo e cerimoniale dello Stato.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Ascesa al trono di Bayezid II a Istanbul", "9b686d04"], "d": ["Secondo la voce Bayezid II del TDV İslâm Ansiklopedisi, lo şehzade Bayezid, sanjak-bey di Amasya, alla notizia della morte del padre giunse rapidamente a Istanbul e salì al trono; con il sostegno dei giannizzeri superò il fratello Cem partito da Konya. Durante l'ascesa ai giannizzeri fu distribuito il consueto dono di ascesa (cülûs bahşişi). Questo cambio sul trono accese anche la miccia della lotta tra i due fratelli.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Cem Sultan si proclama sultano a Bursa", "b355168a"], "d": ["Secondo la voce Cem Sultan del TDV İslâm Ansiklopedisi, Cem, giunto a Bursa attraverso Karaman, prese la città, si proclamò sultano e fece recitare la khutba. Questo breve sultanato terminò con la sconfitta di Cem a Yenişehir da parte delle forze inviate dal fratello maggiore Bayezid II. Per la sconfitta Cem fu costretto a fuggire verso l'Egitto.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Esecuzione di Gedik Ahmed Pascià", "6d75a58c"], "d": ["Secondo la voce Gedik Ahmed Pascià del TDV İslâm Ansiklopedisi, il pascià, noto per la campagna di Otranto e per il gran visirato, fu giustiziato a Edirne per ordine di Bayezid II a causa del suo atteggiamento nella questione di Cem Sultan e della preoccupazione per la sua influenza. La morte di uno dei comandanti più esperti dell'epoca di Maometto il Conquistatore suscitò grande eco a palazzo.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Fondazione della prima stamperia a Istanbul", "04475930"], "d": ["Secondo la voce Matbaa del TDV İslâm Ansiklopedisi, gli emigrati ebrei dalla Spagna, i fratelli David e Samuel ibn Nahmias, fondarono a Istanbul la prima stamperia che stampava in caratteri ebraici. Fu registrata come il primo tentativo di stamperia attivo in territorio ottomano; la stampa in turco con caratteri arabi sarebbe stata possibile molto più tardi, nel XVIII secolo.", "118df98b"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Terremoto della 'Piccola Resurrezione' a Istanbul", "53e3b1d6"], "d": ["Secondo la voce Istanbul del TDV İslâm Ansiklopedisi, il violento terremoto che colpì la città fu ricordato tra la gente come 'Piccola Resurrezione'; si ebbero gravi danni a mura, moschee e molti edifici e numerose vittime. Per ordine di Bayezid II fu avviata nella città una vasta mobilitazione di riparazione e ricostruzione.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Inizio della rivolta di Şahkulu", "3d9a4a90"], "d": ["Secondo la voce Şahkulu Baba Tekeli del TDV İslâm Ansiklopedisi, Şahkulu, alimentato dalla propaganda safavide, raccolse intorno a sé un'ampia massa turcomanna nella zona di Teke e avviò una grande rivolta di carattere religioso-sociale. La rivolta, una delle più serie crisi di sicurezza interna dell'epoca, scosse profondamente l'autorità centrale dello Stato.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Morte di Bayezid II sulla via di Demotika", "c46e98c9"], "d": ["L'ex sultano, partito da Istanbul per recarsi nella città natale di Demotika dopo l'abdicazione, mentre avanzava nella sua portantina, che percorreva appena 5-6 km al giorno, si sentì male nel villaggio di Abalar presso Çorlu e morì il 25 Rebîülevvel 918 (10 giugno 1512). Il TDV İslâm Ansiklopedisi ritiene la causa della morte molto sospetta; secondo alcune fonti locali e straniere si insiste sulla possibilità che sia stato avvelenato. Dopo un regno di trentun anni morì così l'ottavo sultano della discendenza di Osman Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Esecuzione dello şehzade Ahmed per ordine di Selim il Severo", "65abb2f2"], "d": ["Secondo la voce Selim I del TDV İslâm Ansiklopedisi, lo şehzade Ahmed, favorito del padre Bayezid II e principale rivale per il trono, nella lotta intrapresa dopo l'ascesa al trono del fratello Selim fu sconfitto nella piana di Yenişehir e, mentre fuggiva dal campo di battaglia, fu catturato e ucciso. Con questo fatto Selim pose in gran parte fine alla rivalità per il trono tra fratelli e nipoti.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["İbrahim Pascià nominato gran visir", "9c94c1e3"], "d": ["Secondo la voce İbrâhîm Paşa, Makbul del TDV İslâm Ansiklopedisi, İbrahim Pascià, promosso da has odabaşı a beylerbey di Rumelia e lo stesso giorno a gran visir, divenne gran visir il 13 Şâban 929 (27 giugno 1523). Fu una nomina senza precedenti, dal servizio di palazzo direttamente al gran visirato, e mostrava la straordinaria vicinanza di İbrahim Pascià a Solimano il Legislatore.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hayreddin Pascià nominato kapudan pascià", "a0ff6bab"], "d": ["Secondo la voce Barbaros Hayreddin Paşa del TDV İslâm Ansiklopedisi, Hayreddin Pascià, noto per i suoi successi in Algeria, fu chiamato a Istanbul il 6 aprile 1534 e nominato kapudan pascià e beylerbey di Cezâyir-i Bahr-i Sefîd. Questa nomina è considerata l'inizio della ristrutturazione della flotta ottomana e dell'istituzionalizzazione della potenza navale nel Mediterraneo.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pascià diventa gran visir per la prima volta", "ddfcc014"], "d": ["Secondo la voce Rüstem Paşa del TDV İslâm Ansiklopedisi, dopo la rimozione di Hadım Süleyman Pascià per un disaccordo con un visir, il 17 Ramazan 951 (2 dicembre 1544) Rüstem Pascià fu nominato gran visir. Rüstem Pascià, la cui vicinanza al palazzo era aumentata grazie al matrimonio con Mihrimah Sultan, divenne con questa carica uno degli statisti più influenti dell'epoca di Solimano il Legislatore.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi diventa şeyhülislam", "11ed04f8"], "d": ["Secondo la voce Ebüssuûd Efendi del TDV İslâm Ansiklopedisi, Ebüssuûd Efendi, che era stato per otto anni kazasker di Rumelia, fu nominato şeyhülislam in Şâban 952 (ottobre 1545) e rimase in questa carica ventotto anni e undici mesi. Noto per le fatwa che armonizzavano i kanunname di Solimano il Legislatore con il diritto sciaraitico, ebbe un ruolo determinante nel dare forma alle istituzioni giuridiche ed educative della sua epoca.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Morte di Barbaros Hayreddin Pascià", "3378a0bf"], "d": ["Secondo la voce Barbaros Hayreddin Paşa del TDV İslâm Ansiklopedisi, dopo una breve malattia morì a Istanbul il 6 Cemâziyelevvel 953 (5 luglio 1546). La morte di Barbarossa, sepolto a Beşiktaş nel mausoleo adiacente alla madrasa da lui fatta costruire, fu considerata la chiusura di un'epoca della supremazia mediterranea fondata dalla flotta ottomana.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Inizio della costruzione della Moschea e del complesso di Süleymaniye", "101ec36f"], "d": ["Secondo la voce Süleymaniye Camii ve Külliyesi del TDV İslâm Ansiklopedisi, il complesso, di cui furono posate le fondamenta nel 1550 sotto la direzione dell'architetto capo Mimar Sinan, fu concepito come un grande complesso sociale composto, oltre che dalla moschea, da madrase, darüşşifa, imaret e biblioteca. La costruzione fu uno dei più grandi programmi edilizi simbolo della potenza del regno di Solimano il Legislatore e dello sviluppo urbano di Istanbul.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Inizio di una nuova ondata di peste a Istanbul e dintorni", "547d6bf6"], "d": ["Secondo la voce Tâun del TDV İslâm Ansiklopedisi, una delle epidemie del XVI secolo che colpirono il mondo islamico si ebbe tra il 1552 e il 1566 e fu particolarmente incisiva a Istanbul, in Anatolia, Rumelia, Egitto e Nordafrica. Le vie commerciali in espansione e la crescente mobilità della popolazione sono annoverate tra i fattori che facilitarono la diffusione delle epidemie nel periodo di maggior potenza dell'Impero.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed Pascià nominato gran visir", "a7d7748e"], "d": ["Secondo la voce Kara Ahmed Paşa del TDV İslâm Ansiklopedisi, Kara Ahmed Pascià, che era secondo visir, dopo l'improvvisa rimozione del gran visir in carica, il 27 Şevval 960 (5 ottobre 1553) fu promosso gran visir. Questo cambio indica un periodo, coincidente con i giorni dell'esecuzione dello şehzade Mustafa, in cui gli equilibri di potere a palazzo cambiavano rapidamente di mano.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Giustiziato il kapudan pascià Pîrî Reis", "3b2ad7a0"], "d": ["Secondo la voce Pîrî Reis del TDV İslâm Ansiklopedisi, quando giunsero in Egitto le accuse che, togliendo l'assedio di Hormuz, avesse saccheggiato in cambio di tangenti i beni dei musulmani e abbandonato l'esercito sul campo di battaglia, il celebre navigatore e cartografo fu giustiziato al Cairo alla fine del 960 (fine 1553). La morte di Pîrî Reis, i cui beni furono confiscati, è considerata una conseguenza della rivalità tra pascià nella politica navale dell'epoca a Bassora e nell'Oceano Indiano.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Kara Ahmed Pascià giustiziato, Rüstem Pascià di nuovo gran visir", "9a85076a"], "d": ["Secondo le voci Rüstem Paşa e Kara Ahmed Paşa del TDV İslâm Ansiklopedisi, al posto di Kara Ahmed Pascià, improvvisamente giustiziato durante la riunione del divan il 13 Zilkade 962 (29 settembre 1555), con il sostegno delle sultane Hürrem e Mihrimah Rüstem Pascià fu nominato gran visir per la seconda volta lo stesso giorno. I retroscena dell'episodio sono lasciati aperti nelle fonti e sono stati valutati come il risultato di intrighi di palazzo.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Morte di Hürrem Sultan", "1ae998b5"], "d": ["Secondo la voce Hürrem Sultan del TDV İslâm Ansiklopedisi, Hürrem Sultan, che per anni come haseki sultana di Solimano il Legislatore ebbe grande influenza a palazzo, morì a Istanbul il 26 Cemâziyelâhir 965 (15 aprile 1558) e fu sepolta nel suo mausoleo nel complesso della Moschea di Süleymaniye. La morte di Hürrem Sultan, che aveva consolidato la propria autorità sull'harem dopo la morte della valide sultan Hafsa nel 1534, eliminò anche l'effetto equilibratore sulla rivalità per il trono tra i figli Bayezid e Selim.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Sokollu Mehmed Pascià sale al gran visirato", "896391a2"], "d": ["Secondo la voce Sokollu Mehmed Paşa del TDV İslâm Ansiklopedisi, Sokollu Mehmed Pascià, salito al gran visirato alla morte di Semiz Ali Pascià il 30 Zilkade 972 (29 giugno 1565), fu l'ultimo gran visir di Solimano il Legislatore e mantenne la carica anche nei periodi di Selim II e Murad III, divenendo uno dei gran visir rimasti più a lungo in carica nella storia ottomana.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II giunge a Istanbul e sale al trono", "0289ef97"], "d": ["Dopo la morte di Solimano il Legislatore a Szigetvár, la notizia fu tenuta segreta per settimane da Sokollu Mehmed Pascià per non turbare l'ordine. Secondo il TDV İslâm Ansiklopedisi, Selânikî dà come data dell'arrivo di Selim a Istanbul il 15 Rebîülevvel 974 (30 settembre 1566), mentre la maggior parte degli storici contemporanei ritiene corretto il 9 Rebîülevvel (24 settembre). La morte di Solimano fu proclamata ufficialmente a Belgrado solo il 24-25 ottobre 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["La flotta ricostruita da Kılıç Ali Pascià scende in mare", "d0fc9f48"], "d": ["Dopo la grave sconfitta di Lepanto (7 ottobre 1571) per tutto l'inverno si costruirono navi negli arsenali. Secondo il TDV İslâm Ansiklopedisi, il 1° Safer 980 (13 giugno 1572) la nuova flotta composta da 250 galee e circa 300 capitani volontari fu varata con una dimostrazione di forza.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Sokollu Mehmed Pascià ucciso in un attentato", "6ffa8dec"], "d": ["Sokollu Mehmed Pascià, che era stato gran visir per quattordici anni sotto tre sultani, il 20 Şâban 987 (12 ottobre 1579) fu ucciso a pugnalate da un derviscio che, nel divan pomeridiano nella sua dimora, si avvicinò come per presentare una petizione. Secondo il TDV İslâm Ansiklopedisi si discute se l'attentato fosse legato alla vendetta per lo sceicco hamzavita Hamza Bâlî, giustiziato.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Primo ahidnâme commerciale con l'Inghilterra — capitolazioni concesse agli Inglesi", "59c8e3ee"], "d": ["Il rappresentante inglese William Harborne, inviato a Istanbul nell'ottobre 1578, con il sostegno di Sokollu Mehmed Pascià e Hoca Sâdeddin Efendi ottenne da Murad III un ahidnâme datato 1580. Con questo ahidnâme i mercanti inglesi ottennero il diritto di godere nella stessa misura dei privilegi commerciali (capitolazioni) già concessi a Francesi e Veneziani. Tra la regina Elisabetta I e Murad III furono scambiate lettere e si stabilì anche una relazione ufficiale tra i due Stati. Subito dopo questi privilegi nel 1581 fu fondata a Londra la Levant Company; gli Inglesi condussero fino al 1825 il loro commercio nella regione per mezzo di questa società.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Osservatorio di Istanbul demolito con hatt-ı hümâyun", "3bc0c78c"], "d": ["Per l'effetto della fatwa secondo cui gli osservatori portano sventura ai paesi e dell'opposizione a palazzo, con un hatt-ı hümâyun del 4 Zilhicce 987 (22 gennaio 1580) l'Osservatorio di Istanbul fu fatto demolire con tutti gli strumenti al suo interno. Secondo il TDV İslâm Ansiklopedisi questa fu la breve fine dell'istituzione fondata da Takıyyüddin er-Râsıd.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Inizio della festa di circoncisione dello şehzade Mehmed all'Atmeydanı", "c2926d5d"], "d": ["Lo şehzade Mehmed, figlio di Murad III, fu circonciso con sontuose cerimonie iniziate il 6 Cemâziyelevvel 990 (29 maggio 1582) e durate cinquantasei-cinquantasette giorni. Secondo il TDV İslâm Ansiklopedisi i festeggiamenti organizzati all'Atmeydanı furono una delle celebrazioni di palazzo più grandiose della sua epoca.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Morte di Nurbânû Valide Sultan", "77d0a577"], "d": ["Nurbânû Sultan, madre di Murad III, morì il 22 Zilkade 991 (7 dicembre 1583). Secondo il TDV İslâm Ansiklopedisi, come valide sultan aveva tenuto corrispondenza con le corti di Venezia e di Francia, e il senato veneziano nello stesso anno aveva accettato di inviarle un dono del valore di 2000 ducati veneziani per i servigi resi.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Scoppia l'episodio del Beylerbeyi per le akçe adulterate (tağşiş)", "db2f2e61"], "d": ["Quando lo Stato effettuò i pagamenti riducendo la proporzione d'argento dell'akçe, sipahi e giannizzeri assediarono il palazzo e provocarono una sanguinosa rivolta passata alla storia con il nome di Episodio del Beylerbeyi (Beylerbeyi Vak'ası). Secondo la voce Abdülkadir Şeyhî Efendi del TDV İslâm Ansiklopedisi, lo şeyhülislam fu destituito in seguito a questo fatto.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III sale al trono, diciannove şehzade strangolati", "2cd9a8c5"], "d": ["Mehmed III, alla morte del padre Murad III, giunse a Istanbul e salì al trono venerdì 16 Cemâziyelevvel 1003 (27 gennaio 1595). Secondo il TDV İslâm Ansiklopedisi nella stessa notte furono strangolati diciannove şehzade, quattro dei quali adulti (Mustafa, Bayezid, Osman e Abdullah); fu il fratricidio più numeroso della storia ottomana.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sultan acquisisce influenza come valide sultan", "000bec21"], "d": ["Safiye Sultan, consorte di Murad III e madre di Mehmed III, con l'ascesa al trono del figlio salì come valide sultan a una posizione determinante nella politica di palazzo. Secondo il TDV İslâm Ansiklopedisi in questo periodo l'influenza di origine harem raggiunse la dimensione di intervento diretto negli affari di Stato.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III parte in campagna personalmente per la pressione dei giannizzeri", "d3c50656"], "d": ["Nonostante l'opposizione del gran visir Damad İbrahim Pascià, per la pressione dei giannizzeri Mehmed III, primo sultano dopo Solimano il Legislatore a porsi personalmente alla testa dell'esercito, partì da Istanbul per la campagna il 20 giugno 1596. Secondo il TDV İslâm Ansiklopedisi ciò significava la rivitalizzazione dell'antica tradizione del gazâ.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["L'epidemia di peste iniziata negli anni 1570 continuava a colpire Istanbul", "eb4ca37a"], "d": ["Secondo la voce tâun del TDV İslâm Ansiklopedisi, l'epidemia iniziata negli anni 1570 continuò a farsi sentire fino all'inizio del XVII secolo e colpì, in primo luogo Istanbul, Anatolia, Balcani, Egitto e Nordafrica. I periodi epidemici costituivano una minaccia cronica che interrompeva spesso la vita di palazzo e della città.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Muore Karayazıcı Abdülhalim, il movimento di rivolta si indebolisce", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, ritiratosi ferito dopo la grave sconfitta subita il 12 agosto 1601 a Sepetli presso Elbistan, morì nel 1010 (1602). Secondo il TDV İslâm Ansiklopedisi la notizia della morte giunse a Istanbul nel Ramadan del 1010 (febbraio-marzo 1602); le fonti riferiscono che è controverso se la morte sia avvenuta per la ferita o per mano dei suoi stessi uomini.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Fine di fatto della tradizione del fratricidio", "9046c607"], "d": ["Ahmed I, alla sua ascesa, a differenza dei sultani precedenti, non fece uccidere il fratello şehzade Mustafa e gli risparmiò la vita; questa decisione è considerata l'inizio dell'adozione di fatto nel sistema successorio ottomano del criterio ekber-erşed (il più anziano e il più capace). La voce \"Mustafa I\" del TDV İslâm Ansiklopedisi riferisce che da questa data Mustafa condusse a palazzo una vita di mahfil. La pratica pose di fatto fine agli omicidi di ascesa che si protraevano da secoli.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Posa della prima pietra della Moschea del Sultano Ahmed", "1683262f"], "d": ["Per ordine di Ahmed I fu posata con una cerimonia la prima pietra della moschea che l'architetto Sedefkâr Mehmed Ağa avrebbe costruito all'Atmeydanı. Secondo la voce \"Sultan Ahmed Camii ve Külliyesi\" del TDV İslâm Ansiklopedisi, l'edificio fu oggetto anche di critiche dell'epoca per essere la prima grande moschea selâtin costruita direttamente dal tesoro senza una vittoria di conquista. Il complesso fu progettato in modo da includere, oltre alla moschea, anche la madrasa, l'imaret e il mausoleo.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Uccisione di Osman il Giovane da parte dei giannizzeri (Hâile-i Osmâniye)", "324f6582"], "d": ["I giannizzeri e i sipahi, sollevatisi per le voci secondo cui con il pretesto del pellegrinaggio sarebbe uscito da Istanbul per sciogliere il corpo dei giannizzeri, deposero Osman II e lo fecero strangolare nelle prigioni di Yedikule. Secondo la voce \"Osman II\" del TDV İslâm Ansiklopedisi questo fu il primo caso nella storia ottomana in cui un sultano fu ucciso apertamente da una rivolta militare e creò una profonda frattura nel rapporto tra dinastia ed esercito. Le sue ultime ore trascorsero così: dopo che il tentativo di rifugiarsi nella dimora del comandante dei giannizzeri Ali Ağa non ebbe esito, il sultano, nelle parole del TDV 'in modo penoso, a capo scoperto, in condizioni disastrose', fu fatto salire su un cavallo e, sotto pesanti insulti, condotto prima a Orta Cami dove si trovava Mustafa I e, nel pomeriggio dello stesso giorno, a Yedikule; secondo alcuni storici, per provarne la morte gli furono tagliati orecchio e naso e mostrati alla madre di Mustafa I. Dopo il fatto Mustafa I fu fatto salire al trono per la seconda volta. L'episodio, ricordato come 'Hâile-i Osmâniye' (la tragedia di Osman), turbò in modo permanente l'equilibrio palazzo-corpo dei giannizzeri e avviò dispute di legittimità destinate a durare un secolo.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Seconda ascesa al trono di Mustafa I", "34a0b29a"], "d": ["Dopo l'uccisione di Osman il Giovane da parte dei giannizzeri, poiché nella dinastia non c'erano altri membri maschi adulti, Mustafa I fu fatto salire al trono per la seconda volta. Secondo la voce \"Mustafa I\" del TDV İslâm Ansiklopedisi, anche questo secondo sultanato trascorse, non diversamente dal primo, senza poter condurre di fatto gli affari di Stato, e il governo dello Stato rimase in mano ai visir e alla valide sultan. Questo periodo di quattordici mesi si concluse nel 1623 con l'ascesa di Murad IV.", "0fb39afd"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Presa di Köprühisar e preparativi per la fondazione di Yenişehir", "39abff03"], "d": ["Con la caduta delle fortezze di passo tra Bursa e İznik fu posta la base del quartier generale avanzato che avrebbe stretto d'assedio le due città.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Fondazione di Yenişehir", "d3275837"], "d": ["Per dirigere gli assedi di Bursa e İznik fu fondato il primo insediamento-guarnigione ottomano regolare; Orhan Gazi nacque qui.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Primo assedio di İznik e conquista di Marmaracık", "cdca2349"], "d": ["İznik fu assediata per la prima volta ma non cadde (la conquista definitiva è del 1331); nel frattempo fu presa la vicina fortezza di Marmaracık.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Campagna della Compagnia Catalana in Anatolia", "4fd940d5"], "d": ["La compagnia catalana assoldata da Bisanzio per fermare l'avanzata turca ottenne successi temporanei ma non durevoli; con il suo ritiro l'avanzata dei beylik di frontiera si accelerò.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal si converte all'Islam e passa agli Ottomani", "ca0d86e1"], "d": ["Köse Mihal, tekfur di Harmankaya, si convertì all'Islam e si unì a Osman Gazi con la sua fortezza e i suoi uomini; fu il primo comandante ottomano di origine bizantina.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bey assume di fatto il governo", "6dadbefc"], "d": ["Per la vecchiaia e la malattia di Osman Gazi, la direzione e la conduzione effettiva dell'assedio di Bursa e delle campagne passarono al figlio Orhan Bey (l'ascesa ufficiale al trono è del 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Presa di Mudanya", "0a623368"], "d": ["Fu presa Mudanya, porto di Bursa, e il collegamento della città con il mare fu tagliato; l'assedio di Bursa entrò nella fase di strangolamento.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Conquista di Akyazı e dell'isola di İmralı", "d041b0c8"], "d": ["Fu presa Akyazı, a nord del Sakarya; con la conquista dell'isola di İmralı gli Ottomani, per la prima volta, divennero vicini dell'isola di Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Conquista di Gemlik (Kios) e Armutlu", "682d3bac"], "d": ["Tagliato l'ultimo collegamento marittimo di Bursa, la città fu preparata alla resa del 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca conquistò Kandıra e dintorni", "341bb97e"], "d": ["Akça Koca, uno dei beg di frontiera di Orhan Gazi, mentre compiva incursioni nella regione di İzmit dal suo quartier generale a ovest del lago di Sapanca, verso il 1326 si impadronì di Kandıra e dei dintorni. İzmit era ancora in mano bizantina; la città sarebbe caduta solo nel 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Annessione di Yalova e Karamürsel", "133cb07a"], "d": ["Yalova e dintorni, sulla costa meridionale del golfo di İzmit, quest'anno passarono in mano turca; la fascia costiera fu data come timar da Orhan Bey a Karamürsel Gazi.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca prese Aydos e la fortezza di Samandıra", "ce4daa8a"], "d": ["Dopo la presa di Kandıra, Akça Koca insieme a Konuralp e Gazi Abdurrahman prese la fortezza di Aydos presso Kartal e poi la fortezza di Samandıra a nord di essa; la regione di Samandıra gli fu data come proprietà. Akça Koca morì nel 1328 presso Kandıra; il beylik di frontiera fu dato al principe Murad.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Alleanza ottomano-Aydın-Saruhan", "9df6bb74"], "d": ["Tre beylik agirono insieme contro Bisanzio; la flotta di Umur Bey degli Aydınoğlu logorò Bisanzio su un secondo fronte con le incursioni sulle coste della Tracia.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Matrimonio di Orhan Gazi con Teodora: alleanza bizantina", "9b67a590"], "d": ["Orhan Gazi, che nella lotta per il trono bizantino sosteneva Cantacuzeno, sposò la figlia di lui, Teodora; questa alleanza permise alle forze ottomane di conoscere da vicino la Rumelia.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Presa di Ankara", "49bf1f6d"], "d": ["Ankara, retta dagli ahi, entrò nell'amministrazione ottomana; si aprì la strada dell'Anatolia centrale. Altri luoghi annessi nella stessa data: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Avanzata in Tracia al tempo di Süleyman Paşa: Malkara, İpsala e Tekirdağ", "fb31cf02"], "d": ["Dopo aver stabilito la testa di ponte a Gallipoli, Süleyman Paşa salì a nord dalla penisola e conquistò passo dopo passo la pianura tra la costa del Marmara e la foce della Maritza. Malkara, İpsala e Rodosçuk (Tekirdağ) formarono così un corridoio ininterrotto che univa Gallipoli e la valle della Maritza. Senza la costituzione di questo corridoio non si poteva marciare su Edirne; l'avanzata, fermata dalla morte improvvisa del principe nel 1357, sarebbe stata proseguita da Lala Şahin e Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Rapimento del principe Halil", "b52ac3d7"], "d": ["Halil, figlio minore di Orhan Gazi, fu rapito dai pirati di Focea; la crisi del riscatto occupò per anni le relazioni ottomano-bizantine.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Tagliate le vie di soccorso di Edirne: fortezze di Çorlu, Lüleburgaz, Babaeski e Keşan", "8e8ad485"], "d": ["Il principe Murad, ripresa la campagna di conquista dopo la liberazione di Halil, mandò gli akıncı fino alle porte di Costantinopoli per isolare Edirne da ogni aiuto esterno. Furono presi le fortezze di Çorlu, Lüleburgaz e Babaeski sulla strada Costantinopoli-Edirne e Keşan, snodo stradale della Tracia meridionale. La resa di Edirne giunse dopo il completamento di questo anello d'assedio.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Presa di Dimetoka — apertura della valle della Maritza", "b59aee83"], "d": ["Fu presa Dimetoka, fortezza chiave della valle della Maritza; si aprì così la strada della conquista di Edirne. Senza il completamento del corridoio che si estende a nord da Gallipoli non era possibile marciare su Edirne, per questo la fortezza nell'ordine delle conquiste in Rumelia precede Edirne. La città divenne per un periodo il quartier generale dei sultani in Rumelia. Le forze che presero Dimetoka misero poi sotto controllo l'intera regione della media Maritza, insieme a piccole fortezze come Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Perdita di Gallipoli (crociata di Savoia)", "00e7e415"], "d": ["La flotta di Amedeo di Savoia, cugino dell'imperatore bizantino, prese Gallipoli e la consegnò a Bisanzio; la testa di ponte ottomana in Rumelia fu governata per dieci anni dalla sponda opposta dello stretto. Altri insediamenti perduti nella stessa data: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Battaglia di Çirmen — controllo della valle della Maritza", "cd738d8d"], "d": ["L'esercito dei signori serbi fu disperso in un attacco notturno; i signori locali serbi/bulgari della Macedonia e dei Rodopi cominciarono uno per uno a pagare tributo agli Ottomani — non una conquista diretta, ma l'inizio di un'ondata di vassallaggio. Nella tradizione ottomana questa battaglia è narrata anche con il nome di «Sırpsındığı» e con la data del 1364, come attacco notturno di Hacı İlbey contro l'esercito crociato venuto a riprendere Edirne; il TDV afferma che tale data è errata e che le due narrazioni si riferiscono alla stessa battaglia.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Conquista di Filibe e Eski Zağra", "e780c9ae"], "d": ["Furono prese Filibe (Plovdiv), a monte della valle della Maritza, e Eski Zağra (Stara Zagora) a nord; lo zarato bulgaro fu reso tributario. Il percorso Tatarpazarcığı-İhtiman tra Filibe e Sofia rimase in mano ai signori locali divenuti vassalli dopo Çirmen.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bisanzio vassallo: Giovanni V nell'esercito di Murad I (conseguenza della vittoria di Çirmen del 1371)", "13ffe568"], "d": ["Secondo il TDV, dopo la vittoria di Çirmen (Maritza) del 26 settembre 1371 l'Impero bizantino aveva riconosciuto il dominio ottomano e, accettando di pagare tributo e di servire nell'esercito ottomano, era caduto nella condizione di Stato vassallo. L'imperatore Giovanni V, con questo obbligo, nel 1373 si unì all'esercito di Murad I; il figlio Andronico IV, lasciato nel frattempo a Costantinopoli, si ribellò al padre insieme al principe Savcı Bey, a Bursa.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Riconquista di Gallipoli", "5f96c0a5"], "d": ["Andronico IV, che nella contesa per il trono bizantino aveva ottenuto l'appoggio ottomano, in cambio restituì Gallipoli; il ponte tra Rumelia e Anatolia fu ricostituito. Altri luoghi annessi nella stessa data: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Dote germiyanide: annessione di Kütahya", "d6a6fe61"], "d": ["Nel matrimonio di Devletşah Hatun, figlia di Germiyanoğlu Süleyman Şah, con Yıldırım Bayezid, Kütahya, Simav, Tavşanlı ed Eğrigöz passarono agli Ottomani come dote — l'esempio classico di espansione senza guerra. Altri luoghi annessi nella stessa data: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Acquisto del territorio di Hamîd: annessione di Isparta", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bey vendette a Murad I, in cambio di denaro, una parte del suo beylik (Akşehir-Beyşehir-Isparta); il resto del territorio di Hamid sarebbe stato annesso da Yıldırım nel 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Conquista di Serez", "d4d28b60"], "d": ["Fu presa Serez, chiave della Macedonia orientale; Salonicco entrò nel cerchio d'assedio. La linea Köstendil-Petriç-Nevrokop-Drama tra Sofia e Serez a questa data non era ancora annessa direttamente: passò in successione a vassallaggio fra gli anni 1370 e il 1383 e a governo diretto dopo il 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Conquista di Sofia", "96d5f01f"], "d": ["Furono messi sotto controllo i passi occidentali dei monti Balcani; poiché a questa data Serez era già in mano dal 1383, i territori di Tracia e Macedonia formavano un blocco ininterrotto.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Conquista di Niš", "77f5d632"], "d": ["Con la presa di Niš, chiave della valle della Morava, il despotato serbo fu direttamente minacciato.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Prima resa di Salonicco", "96010ee9"], "d": ["Dopo un lungo blocco la città si arrese (sarebbe stata restituita a Bisanzio nel 1403 e conquistata definitivamente nel 1430). Altri luoghi annessi nella stessa data: Kavala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidnâme ottomano-genovese — rinnovo del trattato del 1352", "be11d17a"], "d": ["Con gli ambasciatori genovesi di Pera fu rinnovato l'accordo commerciale del 1352, risalente all'epoca di Orhan Gazi; furono nuovamente fissati le imposte, il trattamento dei prigionieri e il libero commercio tra i due Stati. È considerato il primo ahidnâme ufficialmente noto di amicizia e commercio tra Ottomani e Genovesi — non un'alleanza militare, ma un accordo interamente commerciale.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Campagna di Bulgaria di Çandarlı Ali Paşa: presa di Şumnu e Rusçuk", "2781c3a9"], "d": ["Le fortezze dello zarato bulgaro lungo il Danubio furono prese in una sola campagna; non va confuso con la sconfitta subita nello stesso anno a Bileća in Bosnia — fu un successo simultaneo su un fronte separato. Tırnova e Vidin erano ancora gli ultimi centri bulgari in mano.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Sconfitta di Bileća", "89ba0a64"], "d": ["La forza di akıncı diretta in Bosnia cadde in un'imboscata a Bileća e fu annientata; questa prima grande battuta d'arresto balcanica incoraggiò l'alleanza che condusse al Kosovo.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Annessione dei beylik dell'Anatolia occidentale: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Tre beylik furono annessi in un'unica volta: Manisa, centro dei Saruhanoğulları; Aydın, centro degli Aydınoğulları (compresa la fortezza superiore di Smirne, ma con porto/fortezza bassa ancora ai Cavalieri di San Giovanni — fino al 1402); Muğla-Milas, centro dei Menteşeoğulları, compresa la fascia costiera Datça-Bodrum-Marmaris-Fethiye. Le coste egee furono per la prima volta riunite sotto un'unica mano. Altri luoghi annessi nella stessa data: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Annessione del territorio di Teke: annessione di Antalya", "fdbeee5c"], "d": ["Il territorio di Teke, sulla costa mediterranea, fu annesso ai territori ottomani. I Tekeoğulları sono un ramo staccatosi dagli Hamîdoğulları: Feleküddin Dündar Bey aveva lasciato Antalya, da lui conquistata, al fratello Yûnus Bey e verso il 1321 era nato un beylik separato. Per questo Antalya e dintorni sulla mappa dopo il 1321 sono mostrati con il colore dei Tekeoğulları e non degli Hamîdoğulları. Il beylik fu ricostituito dopo la battaglia di Ankara e fu liquidato in modo definitivo solo nel 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Conquista di Üsküp", "9e5a1af5"], "d": ["Fu presa Üsküp, centro della Macedonia del Vardar; Üsküp divenne uno dei principali centri di frontiera della Rumelia.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Annessione di Kastamonu", "876330ba"], "d": ["Il ramo di Kastamonu dei Candaroğulları fu liquidato; il ramo di Sinope continuò come vassallo. Altri luoghi annessi nella stessa data: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Caduta di Tırnova — annessione della Bulgaria", "ff666977"], "d": ["Cadde la capitale dello zarato bulgaro; la Bulgaria entrò sotto governo ottomano diretto. Altri luoghi annessi nella stessa data: Plevne, Lofça.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["La fortezza di Lofça (Lovech) passa agli Ottomani", "a55e87a0"], "d": ["Lofça, una delle fortezze dello zar bulgaro Ivan Šišman, nella campagna del 1393 in cui cadde Tırnova fu annessa ai territori ottomani insieme alle altre province di Šišman. La fonte non è categorica: si «ritiene» che la conquista sia avvenuta in quest'anno.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Annessione della Dobrugia", "478e36f2"], "d": ["Furono annessi i territori della Dobrugia che si estendono fino al delta del Danubio. Altri luoghi annessi nella stessa data: Silistre, Köstence.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Discesa in Tessaglia", "8bec60dd"], "d": ["La pianura della Tessaglia, centrata su Yenişehir (Larissa), fu posta sotto amministrazione ottomana. Altri luoghi annessi nella stessa data: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["Inizio dello stretto assedio di Costantinopoli (blocco dal ~1387)", "0068bc04"], "d": ["Yıldırım Bayezid tenne Costantinopoli sotto blocco a intervalli per dieci anni; la città si salvò solo per l'avvicinarsi di Tamerlano.", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Battaglia di Rovine — campagna di Valacchia", "343ae7a9"], "d": ["Dopo la battaglia sanguinosa dall'esito controverso con il voivoda di Valacchia Mircea, la Valacchia accettò di pagare tributo agli Ottomani; fu stabilito l'assetto di vassallaggio a nord del Danubio.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Conquista di Nicopoli", "b9791717"], "d": ["Dopo la battaglia di Rovine del 1395 contro i Valacchi, Yıldırım Bayezid prese la fortezza di Nicopoli sul Danubio; alcune cronache bulgare anonime indicano che la conquista avvenne il 3 giugno 1395. La data della conquista non è univoca nelle fonti: la voce Niğbolu Savaşı del TDV İslâm Ansiklopedisi scrive che Bayezid prese Silistra e Nicopoli in una campagna sul Danubio del 1394. La fortezza sarebbe stata assediata nella celebre Crociata del 1396, ma non sarebbe caduta. Altri luoghi annessi nella stessa data: Ohri.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["La fortezza di Nicopoli passò agli Ottomani", "327012c9"], "d": ["Dopo l'incursione di Rovine Yıldırım Bayezid prese Nicopoli; lo zar bulgaro Ivan Šišman, che vi risiedeva come vassallo ottomano, fu eliminato. Nell'atlante Nicopoli è registrata in questo giorno come passata dallo Zarato bulgaro agli Ottomani.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Costruzione di Anadolu Hisarı", "aa259b00"], "d": ["Per sostenere il blocco di Costantinopoli sulla sponda anatolica del Bosforo fu costruita Güzelcehisar (Anadolu Hisarı) — il primo passo duraturo del controllo dello stretto.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Annessione di Vidin", "ee1ae44b"], "d": ["Dopo la vittoria di Nicopoli fu annesso anche Vidin, ultimo principato bulgaro.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Prima annessione di Karaman", "3cf07876"], "d": ["Con la vittoria di Akçay i territori dei Karamanoğulları furono annessi per la prima volta agli Ottomani (sarebbero stati ricostituiti durante il Fetret).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Annessione delle coste del Canik: Samsun", "af9c40fa"], "d": ["Nel vuoto creato dalla cattura di Kadı Burhâneddin da parte dell'aqquyunlu Karayülük Osman Bey, Yıldırım Bayezid pose dapprima sotto amministrazione ottomana la regione del Canik, sulla costa del Mar Nero. Samsun e dintorni divennero così il primo porto del Mar Nero della dinastia. La linea interna Sivas-Tokat-Kayseri sarebbe stata annessa due settimane dopo, con la dissoluzione di fatto dello Stato di Kadı Burhâneddin.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Presa di Malatya", "7cb6ae16"], "d": ["Fu conquistata Malatya, sul confine mamelucco — uno dei passi che accrebbero la tensione con Tamerlano.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Tamerlano prese Malatya e la lasciò a Karayülük Osman — quando Tamerlano si ritirò i Dulkadiroğulları la ripresero", "ad2ce7d8"], "d": ["Yıldırım Bayezid, lasciata Malatya, presa nel 1399, a Dulkadıroğlu Nasreddin Mehmed, era tornato a Bursa. Tamerlano, entrato in Anatolia nel 1400, prese prima Sivas ed Elbistan, poi Malatya; la città e i dintorni furono saccheggiati e l'amministrazione fu lasciata a Karayülük Osman, che era con Tamerlano. Quando Tamerlano lasciò la regione, Malatya fu di nuovo dominata dai Dulkadiroğulları; il dominio ottomano terminò dunque prima di Ankara.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Accordo di Süleyman Çelebi con Bisanzio: restituzione di Salonicco", "cc503cc2"], "d": ["Süleyman Çelebi, che durante il Fetret dominava la Rumelia, accordandosi con Bisanzio e con gli Stati latini, abbandonò a Bisanzio Salonicco e le coste del Mar Nero fino a Misivri (TDV fetret-devri: Trattato di Gallipoli, febbraio 1403) — sulla mappa İğneada, Rezve e Ahtapolu passano a Bisanzio; Salonicco a questa data esce dagli Ottomani.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Sconfitta navale di Gallipoli (Venezia)", "b71d4d68"], "d": ["La flotta veneziana inflisse una dura sconfitta alla flotta ottomana davanti a Gallipoli; l'evento mostrò i limiti della marineria ottomana delle origini.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Rivolta di Düzmece Mustafa", "0ec43138"], "d": ["Mustafa Çelebi, che sosteneva di essere figlio di Yıldırım, con l'appoggio bizantino proclamò il sultanato in Rumelia; Murad II represse la rivolta nel 1422 e fece giustiziare il rivale.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Assedio di Costantinopoli di Murad II", "4b9d9fba"], "d": ["In risposta al sostegno bizantino a Düzmece Mustafa, Murad II assediò Costantinopoli; l'assedio fu tolto quando il fratello Küçük Mustafa fu fatto insorgere in Anatolia.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Cessione di Salonicco a Venezia", "bfa6c4a0"], "d": ["Il governatore bizantino, sotto la pressione ottomana, cedette la città a Venezia; iniziò la contesa ottomano-veneziana destinata a durare sette anni.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Nuova annessione dei beylik dell'Anatolia occidentale: Menteşe e Aydın", "aca30a48"], "d": ["I due beylik egei ricostituiti durante il Fetret Devri furono definitivamente annessi ai territori ottomani sotto Murad II. Secondo la voce Menteşeoğulları del TDV, Murad II conquistò il territorio di Menteşe nell'827 (1424) e fece imprigionare i due fratelli a capo del beylik. Secondo la voce Aydınoğulları, il beylerbey d'Anatolia Hamza Bey fece catturare Cüneyd Bey, di nuovo uscito dall'obbedienza, e lo fece giustiziare con la sua famiglia (829/1425-26), e il territorio di Aydın passò agli Ottomani. I Cavalieri di San Giovanni, che dal 1344 tenevano la fortezza portuale di Smirne, l'avevano perduta nel 1402 a favore di Tamerlano e la regione era tornata sotto il controllo degli Aydınoğulları; con questa annessione anch'essa fu annessa agli Ottomani. Il territorio di Teke (Antalya) non è oggetto di questa voce: i Tekeoğulları erano stati liquidati separatamente nel 1423. Germiyan sarebbe invece stato annesso nel 1429 per testamento.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Annessione di Germiyan per testamento", "9eb86b77"], "d": ["Il bey di Germiyan Yakub II, morto senza figli, lasciò il paese agli Ottomani per testamento — l'esempio da manuale di annessione senza guerra. Altri luoghi annessi nella stessa data: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Conquista definitiva di Salonicco", "bc021768"], "d": ["La città, sotto dominio veneziano, fu presa d'assalto; il secondo grande porto della Rumelia divenne definitivamente ottomano. Altri luoghi annessi nella stessa data: Kesendire (Cassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Resa di Ioannina", "ee45cb52"], "d": ["Ioannina, centro dell'Epiro, si arrese con un accordo.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Prima presa di Smederevo", "c11ca17d"], "d": ["Con un assedio di tre mesi fu presa la capitale del despotato serbo e la Serbia fu annessa per la prima volta (sarebbe stata restituita con il trattato di Edirne-Seghedino del 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Assedio di Belgrado (fallito)", "3e05f425"], "d": ["Il primo grande assedio di Belgrado, durato sei mesi, non diede risultati; per ottant'anni la fortezza rimase come chiave di volta davanti all'avanzata ottomana.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Disfatta di Zlatica — la «Lunga Campagna»", "97df1466"], "d": ["L'esercito che Hunyadi aveva portato nei Balcani in pieno inverno, superate Niš e Sofia, giunse fino a Zlatica; la difesa ottomana resse a fatica. Questo clima di disfatta portò al tavolo la pace di Edirne-Seghedino.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Trattato di Edirne-Seghedino", "0aa4e0de"], "d": ["Pace decennale: il despotato serbo fu restituito, il Danubio fu accettato come confine. La rottura del trattato nel giro di mesi, per istigazione papale, condusse al disastro di Varna.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Restituzione di Smederevo e delle fortezze serbe alla Serbia", "cda3cf9e"], "d": ["La disposizione del trattato di Edirne-Seghedino fu messa in esecuzione: Murad II il 15 agosto 1444 restituì a Đurađ Branković Smederevo con le sue ventiquattro importanti fortezze e gli altri territori serbi occupati (TDV semendire); anche Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) e Priştine (TDV pristine) furono lasciate ai Serbi. Vidin, non essendo territorio serbo, non entrò nella restituzione — è questa l'origine della perdita territoriale nord-occidentale visibile sulla mappa intorno alla vittoria di Varna; pochi mesi dopo, con la disfatta di Varna, il trattato sarebbe comunque decaduto.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Completato Rumeli Hisarı — il «Taglia-Stretto»", "480e8a76"], "d": ["Con la fortezza, completata secondo le fonti in una costruzione straordinariamente rapida di quattro o cinque mesi, il controllo dello Stretto passò interamente agli Ottomani; la via di soccorso dal Mar Nero a Costantinopoli fu chiusa. È considerato il primo passo effettivo dell'assedio.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Inizio dell'assedio di Costantinopoli", "8af50742"], "d": ["L'esercito si dispose davanti alle mura; nell'assedio, destinato a durare 54 giorni, i cannoni giganteschi furono usati per la prima volta in modo sistematico contro le mura di una capitale.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Le navi calate dalla terra nel Corno d'Oro", "4f2ba07c"], "d": ["Circa 70 navi della flotta, che non poteva entrare nel Corno d'Oro chiuso dalla catena, furono trasportate sopra le alture di Galata su slitte unte e calate in una notte nel Corno d'Oro; la difesa fu divisa in due fronti.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Conquista di Atene", "4f0f1bb2"], "d": ["Il Ducato di Atene finì; sull'Acropoli fu issata la bandiera ottomana. Altri luoghi annessi nella stessa data: İstefe (Tebe), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Annessione della Serbia (caduta di Smederevo)", "75fd0a62"], "d": ["Smederevo, capitale del despotato serbo, si arrese; la Serbia divenne un sancak ottomano.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Conquista della Morea", "7d5a3c18"], "d": ["Il despotato di Morea fu liquidato; la penisola (escluse le fortezze veneziane) entrò sotto amministrazione ottomana.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Annessione di Sinope", "e03c2739"], "d": ["Il candaroğlu consegnò Sinope senza combattere; si aprì la strada della campagna di Trebisonda. Altri luoghi annessi nella stessa data: Kastamonu, Bartın, Safranbolu. La voce Candaroğulları del TDV cita anche Bolu, Eflani e Tosya tra i territori del beylik dei Candaroğlu annessi nel 1461; nell'atlante anche questi tre luoghi sono registrati in questo giorno come passati dai Candaroğlu agli Ottomani.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Caduta del Regno di Bosnia — campagna di Bosnia del Conquistatore", "5362e3f2"], "d": ["Quando l'ultimo re di Bosnia, Stjepan Tomašević (1461-1463), confidando nel sostegno occidentale, rifiutò di pagare il tributo, fu considerato decaduto dalla condizione di sovrano soggetto e l'esercito sotto Mehmed il Conquistatore liquidò il Regno di Bosnia in una sola campagna. Il re fu catturato e giustiziato, il regno scomparve e nella regione fu istituito il sancak di Bosnia. Tuttavia la caduta del regno non è la stessa cosa della conquista della Bosnia. L'amministrazione ottomana era già presente nella pianura da quindici anni — Hodidjed e la piana di Saray erano state prese nel 1448 e il beylik di frontiera di Îsâ Bey era stato fondato in mezzo al regno. La conquista non finì neppure nel 1463: Foça nel 1465, Livno nel 1469, il Ducato di Erzegovina nel 1483, il banato di Srebrenik nel 1512, Yayça e Banaluka a nord solo nel 1528, dopo Mohács — gli Ungheresi, dopo il 1463, avevano costituito nel nord della Bosnia un banato che resistette sessantacinque anni. Il luogo che cambia direttamente mano a questa data è Travnik; Yayça passa invece in questa data non agli Ottomani ma all'Ungheria.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Annessione definitiva di Karaman", "f1dcecaa"], "d": ["I territori centrali dei Karamanoğulları furono annessi in modo definitivo; le lotte interne durarono fino agli anni 1470. Altri luoghi annessi nella stessa data: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Conquista di Negroponte", "5c97daf3"], "d": ["Cadde Negroponte, principale base veneziana nell'Egeo.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Annessione di Alanya, Anamur e Silifke (İçel)", "a0b9d461"], "d": ["La fascia costiera dell'İçel, dipendente dai Karamanoğulları (l'intero Mediterraneo tra Antalya e Mersin), fu annessa con la campagna navale di Gedik Ahmed Paşa; Alanya era importante per il suo arsenale strategico di epoca selgiuchide.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Annessione di Novgorod a Mosca", "bed87170"], "d": ["Il granduca Ivan III tolse la campana simbolica dell'assemblea popolare (veče) di Novgorod, sostituì le autorità locali con i propri governatori e legò di fatto la città a Mosca; Novgorod cessò di essere una repubblica indipendente. Il territorio di Novgorod si estendeva dal Mar Baltico al Mar Bianco e agli Urali. Nell'atlante Novgorod è registrata in questo giorno come passata dalla Repubblica di Novgorod a Mosca.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Trattato di Costantinopoli — Albania e Scutari", "b09652f7"], "d": ["La guerra ottomano-veneziana di 16 anni terminò; Scutari e le coste albanesi rimasero agli Ottomani. Altri luoghi annessi nella stessa data: Limni, Sisam, Bozbaba (Ay Strati).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Sbarco a Otranto", "7916b89d"], "d": ["Le forze ottomane sbarcate sulla costa della Puglia (Apulia) assediarono e presero la fortezza di Otranto; poiché si entrò in città combattendo, una parte dei notabili che avevano resistito fu giustiziata e un'altra parte presa prigioniera. La tradizione ecclesiastica ricorda i morti come i «martiri di Otranto», circa 800 persone; il TDV attribuisce l'esagerazione di questo numero alla propaganda ecclesiastica. Furono tenute solo la fortezza all'estremità della penisola salentina e il suo ristretto circondario; gli altri territori del Regno di Napoli sulla linea Taranto-Brindisi-Lecce non andarono perduti — questa testa di ponte aperta sull'Italia sarebbe durata un anno.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evacuazione di Otranto", "37371bb0"], "d": ["Alla morte di Mehmed il Conquistatore (3 maggio 1481), senza più speranza di nuovi rinforzi, la guarnigione di Otranto, di fronte all'assedio dell'erede al trono di Napoli Alfonso, evacuò la fortezza per accordo; l'unica testa di ponte ottomana in Italia andò così perduta un anno dopo.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Conquista di Modone e Corone", "38b608c4"], "d": ["Furono prese Modone e Corone, i «due occhi» di Venezia in Morea.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Conquista di Durazzo", "1f231b98"], "d": ["Durante la guerra ottomano-veneziana del 1499-1503, le forze al comando di Mehmed Bey presero Durazzo, l'ultimo grande porto albanese di Venezia sull'Adriatico. Dopo Scutari (1479) e Valona (1417), con questa conquista la fascia costiera albanese passò interamente sotto il controllo ottomano.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Annessione dell'Anatolia orientale", "e0cb8f8f"], "d": ["Dopo Çaldıran furono annessi Diyarbakır e dintorni; i beylik curdi furono legati agli Ottomani per opera di İdrîs-i Bitlisî.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Conquista della fortezza di Varadino (Petrovaradin)", "abf392a5"], "d": ["L'esercito partito per la campagna di Mohács passò da Belgrado nelle terre ungheresi; di Varadino furono prese prima le periferie e, dopo un assedio di quattordici giorni, cadde anche la fortezza. Solimano ordinò di non bruciare i villaggi lungo la strada, perché ormai erano considerati terra ottomana.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Resa di Buda dopo Mohács — due re sul trono ungherese", "9d3568a0"], "d": ["All'esercito ottomano che marciava su Buda dopo la vittoria di Mohács le chiavi della città furono presentate al sultano l'11 settembre 1526; ma Solimano non tenne Buda e ritirò l'esercito. Nell'Ungheria rimasta senza re i nobili elessero due re distinti: János Szapolyai il 10 novembre 1526 e il 17 dicembre 1526 l'asburgico Ferdinando I. Ferdinando prese Buda nell'agosto 1527. L'insediamento di Szapolyai a Buda come re sotto protezione ottomana avverrà con la campagna del 1529 (si veda la voce del 1529); il governo ottomano diretto sarebbe stato stabilito nel 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai eletto re d'Ungheria — gli Ottomani riconobbero il suo regno a condizione che fosse vassallo", "32bc6baf"], "d": ["Per il trono ungherese rimasto vacante con la morte del re a Mohács una parte dei nobili elesse János Szapolyai, voivoda di Transilvania; Szapolyai fu incoronato a Székesfehérvár. Gli Ottomani, che avevano lasciato Buda, per tenere la regione come zona cuscinetto riconobbero il regno di Szapolyai a condizione che fosse loro vassallo. Sulla mappa i luoghi legati a Szapolyai appaiono da questa data come vassalli degli Ottomani.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinando I proclamato re d'Ungheria — l'Ungheria occidentale e settentrionale alla corona asburgica", "b3910a2f"], "d": ["L'arciduca asburgico Ferdinando, in base al matrimonio della sorella con Luigi II, avanzò pretese sul trono ungherese e fu proclamato re da una parte dei nobili. L'Ungheria fu così divisa tra due re; la parte occidentale e settentrionale riconobbe Ferdinando. I nobili croati lo elessero a parte all'inizio del 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Contesa dei due re: Esztergom sotto protezione asburgica, Szeged a Szapolyai", "da92dee5"], "d": ["Esztergom, che dal 1526 passava di mano tra i due re, dopo che l'arcivescovo si trasferì a nord con l'archivio e il tesoro, entrò sotto la protezione asburgica. Dallo stesso anno fino al 1541 Szeged rimase sotto il dominio di Szapolyai.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Gli abitanti di Pécs passarono dalla parte di Szapolyai", "3fc4e7f2"], "d": ["Pécs, che nel 1528 aveva ottenuto privilegi da Ferdinando, poco dopo passò dalla parte di Szapolyai; re János nel 1533 soggiornò per un periodo in città. Con la caduta di Buda nel 1541 la città tornò dalla parte di Ferdinando.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Conquista di Tripoli", "8c659986"], "d": ["Tripoli fu presa ai cavalieri di San Giovanni; la costa centrale del Nord Africa divenne ottomana. Altri luoghi annessi nella stessa data: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Conquista di Timișoara", "e9fd4995"], "d": ["Fu presa la regione del Banato e fu istituito il Beylerbeylik di Timișoara.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Conquista definitiva di Tunisi", "7bbd11bc"], "d": ["Tunisi, sotto controllo ispano-hafside, entrò definitivamente nell'amministrazione ottomana; la linea nordafricana fu completata. Altri luoghi annessi nella stessa data: Kayrevan, Gabes, Sfaks.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Conquista di Kanije", "0c7b6aa3"], "d": ["Nella Lunga Guerra fu presa Kanije; l'anno seguente la difesa di Tiryâki Hasan Paşa divenne epica.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Inizio della campagna di Uyvar — Fâzıl Ahmed Paşa marciò da Edirne contro l'Austria", "306a86db"], "d": ["Dopo che l'Austria aveva attaccato la Transilvania e preso le fortezze di Székelyhíd e Cluj, Costantinopoli decise la campagna contro gli Asburgo. Il gran visir Köprülüzâde Fâzıl Ahmed Paşa partì da Edirne il 13 aprile 1663. A Belgrado giunse la richiesta di pace dell'Austria, ma in due colloqui a Osijek le condizioni ottomane furono respinte. Anche nella consultazione di Buda l'obiettivo fu fissato in Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Conquista di Uyvar", "ce289470"], "d": ["Fu presa Uyvar, fortezza chiave dell'Ungheria settentrionale; l'espressione «forte come un Turco davanti a Uyvar» passò nelle lingue europee. Dopo Uyvar anche Nitra e Léva si arresero con breve resistenza; entrambe furono riprese da De Souches nella primavera del 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Riconquista della Morea", "9b6460f1"], "d": ["La Morea, lasciata a Venezia a Karlowitz, fu ripresa in una sola campagna. Altri luoghi annessi nella stessa data: Balyabadra (Patrasso), İnebahtı.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Seconda perdita di Belgrado — assedio del principe Eugenio", "6a194354"], "d": ["Dopo la disfatta di Varadino e la perdita di Timișoara il principe Eugenio assediò Belgrado; quando fu sconfitto anche l'esercito di soccorso venuto a salvare la città, la fortezza si arrese. La città, ripresa nel 1690 dopo Karlowitz, andò così nuovamente perduta e la linea difensiva del Danubio crollò. Belgrado avrebbe potuto essere ripresa solo ventidue anni dopo, con il trattato di Belgrado del 1739. Altri insediamenti perduti nella stessa data: Semendire. L'atlante assegna inoltre in questo giorno agli Asburgo le zone di Hisarcık (Grocka) e Yagodina (Jagodina) (giorno di zona; il giorno a livello di luogo non è nella fonte, approssimazione dichiarata); Mehádia passa invece agli Asburgo con la data del 27 agosto 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Caduta di Özi", "90a67a6c"], "d": ["Özi, fortezza chiave a nord del Mar Nero, cadde in mano russa con un sanguinoso assalto; la popolazione della città fu passata a fil di spada.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Trattato di Bucarest — perdita della Bessarabia", "932da4d6"], "d": ["Con il trattato che pose fine alla guerra russa del 1806-1812, l'est del Prut (Bessarabia) fu lasciato alla Russia. Altri insediamenti perduti nella stessa data: Akkirman, Kili, Hotin, Bender, İsmail. L'atlante considera inoltre passati nello stesso giorno dalla Moldavia (vassalla ottomana) alla Russia Kişinev (Chișinău), Bălți, Kahul (Cahul) e Orhei all'interno della Bessarabia. Anche Soroka (Soroca) passa alla Russia nello stesso giorno.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Trattato di Edirne", "b3a8fe4c"], "d": ["Al termine della guerra in cui l'esercito russo entrò a Edirne fu perduto il delta del Danubio; l'autonomia/indipendenza della Grecia fu di fatto accettata. Altri insediamenti perduti nella stessa data: İbrail, Anapa, Ahıska. Benché il trattato restituisse il territorio, non pose subito fine all'occupazione: Valacchia-Moldavia e Silistra rimasero come pegno sotto amministrazione russa fino al pagamento dell'indennità di guerra — è per questo che sulla mappa questi luoghi appaiono occupati anche dopo il 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Firmano di autonomia alla Serbia — knezato ereditario e condizione della guarnigione", "6a5d901d"], "d": ["Il hatt-ı hümâyun emanato in base alla disposizione del trattato di Edirne relativa alla Serbia riconobbe Miloš Obrenović knez ereditario e fece della Serbia un principato autonomo, libero negli affari interni e vassallo degli Ottomani all'esterno. Disposizioni: il knezato sarebbe passato di padre in figlio, il tributo annuo sarebbe stato pagato in somma fissa, l'assemblea serba avrebbe costituito la propria amministrazione interna, la chiesa sarebbe stata autonoma; in cambio nelle fortezze di Belgrado, Smederevo, Šabac, Böğürdelen e Fethülislâm sarebbero rimaste guarnigioni ottomane. Questa struttura doppia durò fino al ritiro delle guarnigioni nel 1867. Sulla mappa la città di Belgrado a questa data viene annessa alla Serbia autonoma; la fortezza di Kalemegdan è mostrata con guarnigione ottomana fino al 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Cessione di Cipro all'amministrazione britannica", "423da3ee"], "d": ["In cambio di un'alleanza contro la minaccia russa l'amministrazione di Cipro fu ceduta all'Inghilterra; giuridicamente rimase territorio ottomano. Altri insediamenti perduti nella stessa data: Lefkoşa, Magosa, Girne, Limasol, Larnaka (Tuzla), Baf, Güzelyurt (Morphou), Akrotiri, Episkopi, Dikelya (Dhekelia); cioè l'intera isola.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Cessione della Tessaglia alla Grecia", "ac614d24"], "d": ["In base alle decisioni del Congresso di Berlino la Tessaglia e la zona di Narda furono cedute alla Grecia. Altri insediamenti perduti nella stessa data: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia). Con questa cessione Golos (Volos), Kalabaka e Kardiçe (Tessaglia) passarono alla Grecia.", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Unione della Rumelia orientale alla Bulgaria", "ee43f137"], "d": ["La provincia autonoma di Rumelia orientale fu unita alla Bulgaria con un colpo di mano; la Sublime Porta accettò il fatto compiuto. Con questa unione l'intera Rumelia orientale (Eski Zağra, Tatarpazarcığı, İslimye, Hasköy, Burgaz, Aydos, Elhova) passò al Principato di Bulgaria.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Battaglia di Domokos", "9c6f29a5"], "d": ["Nella guerra ottomano-greca del 1897 l'esercito ottenne una vittoria decisiva a Domokos; per la pressione diplomatica i guadagni territoriali rimasero limitati.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomia a Creta", "2e764881"], "d": ["Benché la guerra ottomano-greca fosse terminata con una vittoria ottomana, Inghilterra, Russia, Francia e Italia il 18 dicembre 1897 proclamarono l'autonomia di Creta; l'isola sarebbe stata una provincia neutrale e autonoma sotto sovranità ottomana. Dopo il 6 novembre 1898 a Candia e a Kisamo la bandiera turca non fu più issata; con l'entrata in carica del principe Giorgio, figlio del re di Grecia, come commissario straordinario il 22 dicembre 1898, Creta uscì di fatto dall'amministrazione ottomana (se ne separò ufficialmente nel 1913). Altri insediamenti perduti nella stessa data: Kandiye (Creta), Hanya.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Indipendenza della Bulgaria e annessione della Bosnia", "393feaa4"], "d": ["Nel caos della Monarchia Costituzionale la Bulgaria proclamò l'indipendenza e l'Austria-Ungheria annesse la Bosnia-Erzegovina. Con questa proclamazione tutti i territori del Principato di Bulgaria (Varna, Şumnu, Rusçuk, Burgaz, İslimye ecc.) divennero il Regno di Bulgaria indipendente.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Riconquista di Edirne", "536e5599"], "d": ["Nella Seconda guerra balcanica l'esercito attraversò la Maritza e riprese Edirne senza combattere. Altri luoghi annessi nella stessa data: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Vittoria di Kut al-Amara", "98b972bc"], "d": ["Il comandante della divisione britannica assediata a Kut si arrese con 13 mila soldati — una delle più grandi vittorie ottomane della Prima guerra mondiale.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Perdita di Baghdad", "2c18a816"], "d": ["La Baghdad ottomana, dopo 383 anni, passò all'esercito britannico. Altri insediamenti perduti nella stessa data: Kerbelâ.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Perdita di Gerusalemme", "94067617"], "d": ["La Gerusalemme ottomana, dopo 401 anni, fu consegnata senza poter essere difesa.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Perdita di Damasco", "ed177b68"], "d": ["Con il crollo del fronte della Palestina Damasco fu evacuata; il governo ottomano di quattro secoli in Siria ebbe termine. Altri insediamenti perduti nella stessa data: Hama, Humus.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Resa di Medina", "76b505f6"], "d": ["Settantadue giorni dopo l'armistizio la resistenza di Fahreddin Paşa, la «Tigre del Deserto», terminò per volontà del sultano; l'ultima unità ottomana nel Hegiaz depose le armi.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Occupazione di Smirne", "e32e5e77"], "d": ["L'esercito greco sbarcò a Smirne; la resistenza iniziata con il primo colpo di fucile accese la miccia della Guerra di Liberazione Nazionale. Aydın fu invece occupata il 27 maggio 1919 (voce separata).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Occupazione ufficiale di Costantinopoli", "a8e98ada"], "d": ["Le forze dell'Intesa occuparono ufficialmente Costantinopoli e il Meclis-i Meb'ûsan fu sciolto; i deputati si diressero ad Ankara.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Trattato di Kars", "bb32d4e0"], "d": ["Tra la Grande Assemblea Nazionale e le repubbliche caucasiche fu tracciato il confine orientale nella sua forma attuale.", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Presa dell'emirato di Ha'il da parte delle forze saudita-wahhabite — il governo era nella famiglia Ibn Ali della tribù Abde", "2d29ceb9"], "d": ["Quando le forze del Primo Stato saudita presero l'emirato di Ha'il, l'amministrazione della città era nella famiglia Ibn Ali della tribù Abde dei Shammar. Questa famiglia governò Ha'il fino alla presa dell'emirato da parte di Abdallah b. Rashid nel 1835; la dinastia dei Rashidi fu fondata solo in quella data. Nell'atlante Ha'il fino a oggi appariva priva di proprietario fino al 1836, mentre la fonte dà già nel 1820 il nome dell'emiro della città.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Passaggio delle isole del Quarnaro al Regno d'Italia napoleonico e delle Bocche di Cattaro all'amministrazione russa", "c5e411c8"], "d": ["Dopo il Trattato di Presburgo le isole del Quarnaro — a differenza della Dalmazia — furono legate non direttamente alla Francia ma al Regno d'Italia di Napoleone; entrarono nelle Province Illiriche solo nel 1809. Nelle Bocche di Cattaro invece l'amministrazione austriaca terminò e tra il 1806 e il 1807 fu stabilita un'amministrazione russa; le Bocche passarono alla Francia solo nel 1807. Queste due distinzioni non si possono rendere con un'unica finestra 'Francia' dell'atlante.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Passaggio della Dalmazia all'amministrazione francese — applicazione del Trattato di Presburgo (Pojun)", "00bfe4f6"], "d": ["Il Trattato di Presburgo (Pojun, Bratislava) del 26 dicembre 1805 costrinse l'Austria a rinunciare a Istria, Dalmazia e a tutte le isole dell'Adriatico. La Francia rilevò di fatto l'amministrazione nel febbraio 1806; Zara rimase sede del provveditore generale e dal 1806 al 1810 questo incarico fu svolto dal veneziano Vincenzo Dandolo. La Dalmazia dopo il Trattato di Schönbrunn del 1809 fu aggregata alle Province Illiriche. La prima amministrazione austriaca, in corso dal 1797, ebbe così fine — nell'atlante questo periodo fino a oggi appariva come ininterrottamente austriaco.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Ripresa da parte dell'Austria delle Province Illiriche e della Dalmazia — fine dell'amministrazione napoleonica", "1b2ac942"], "d": ["Alla fine del 1813 le truppe asburgiche ripresero la regione a sud della Sava e fu ristabilita l'antica organizzazione di confine; l'esercito austriaco entrò in Istria nell'ottobre 1813. Karlovac da quella data divenne parte del Regno d'Illiria austriaco. Anche il periodo dell'amministrazione francese in Dalmazia si chiuse nel 1813. L'appartenenza della regione all'Austria fu confermata ufficialmente dalla Pace di Parigi del 1814 e dalle decisioni del Congresso di Vienna del 1815. Con questa operazione Villach, Tarvisio, Gorizia, Gradisca e Pola (Province Illiriche) tornarono all'Austria alla fine del 1813.", "bf1e49a8"]}
});
